INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(306515, 'ruRU', '', 'Надеюсь, ты будешь часто заглядывать в наш городок. Но я понимаю, что у тебя немало дел и в других местах. Я буду молить Элуну, чтобы она всегда указывала тебе дорогу домой.', 64978),
(306514, 'ruRU', '', 'Когда-нибудь тебе снова понадобятся услуги Джорвана. Обращайся к нему, когда захочешь расширить дом.', 64978),
(306513, 'ruRU', '', 'Поговори с Джорваном Лонгмуром. Его предки построили здесь первые дома. Мастерство зодчего у него в крови.', 64978),
(306512, 'ruRU', '', 'Я хочу обсудить еще один вопрос, касающийся твоего дома. Надеюсь, ты не против.', 64978),
(306511, 'ruRU', '', 'В городе есть несколько торговцев, предлагающих мебель для дома. Почему бы тебе не заглянуть к ним и не представиться?', 64978),
(306510, 'ruRU', 'Надеюсь, это место уже стало для тебя домом. Но я понимаю, что приключения часто зовут тебя в путь. Да хранит тебя Мать-Земля, и пусть твои странствия всегда приводят сюда.', '', 64978),
(306509, 'ruRU', 'Однажды ты вновь почувствуешь, что твой дом пора расширить. Когда этот день настанет, просто вернись к Роте.', '', 64978),
(306508, 'ruRU', 'Обратись к Роте. Ее команда мигом преобразит твое жилище. Просто расслабься и смотри, как они работают.', '', 64978),
(306507, 'ruRU', 'Надо еще кое-что обсудить по поводу твоего дома. Подходи, когда сможешь.', '', 64978),
(306506, 'ruRU', 'Тебе стоит кое-кого проведать на общем круге. Загляни к ним, когда сможешь. Они продают самые разные товары для дома. Вдруг тебе что приглянется?', '', 64978),
(306461, 'ruRU', '', 'Если тебя такое не смутит, недалеко отсюда торгуют контрабандисты. Они продают товары, привезенные из Орды – помимо всего прочего.', 64978),
(306457, 'ruRU', 'Мы привезли кое-что особенное из Вол\'дуна. Хочешь посмотреть?', '', 64978),
(306436, 'ruRU', '', 'Если хочешь найти другие источники домашнего декора, поговори с последним архитектором. У него повсюду есть связи.', 64978),
(306433, 'ruRU', 'Пока ты здесь, поговори еще с последним архитектором. Думаю, он подскажет, где еще можно поискать мебель для твоего дома.', '', 64978),
(306431, 'ruRU', 'Советую встретиться еще с одной группой. Я о контрабандистах. Мы сквозь пальцы смотрим на их делишки, а они делятся с нами товарами из Альянса.', '', 64978),
(305930, 'ruRU', 'Романы, повести, исследовательские записи! Какими бы ни были твои читательские предпочтения, ты всегда найдешь здесь идеальную книгу для себя.', 'Романы, повести, исследовательские записи! Какими бы ни были твои читательские предпочтения, ты всегда найдешь здесь идеальную книгу для себя.', 64978),
(305893, 'ruRU', 'Конечно. Что ты хочешь найти?', '', 64978),
(305884, 'ruRU', '', 'Ой, прости. У нас тут ничего такого нет.\n\nНо до меня доходили слухи, что иногда на остров прибывают подозрительные гости. Я к ним еще не заглядывала, но, может, они тебе помогут?', 64978),
(305882, 'ruRU', '', 'О, тебе к Тревору.\n\nОн наш специалист по садоводству. Ты найдешь у него все, что нужно.', 64978),
(305878, 'ruRU', '', 'Бален Звездоискатель – главный знаток эльфийского декора в нашем районе.\n\nДумаю, ты найдешь у него то, что тебе нужно.', 64978),
(305876, 'ruRU', '', 'Загляни в лавку Фаардена.\n\nОн сотрудничает с местными ремесленниками и собрал впечатляющий ассортимент декора.', 64978),
(305874, 'ruRU', '', 'Что ты хочешь найти?', 64978),
(305438, 'ruRU', '<Моментий некоторое время обдумывает ваши слова.>\n\nСмелая аналогия, $p. Ковка – это процесс, в котором удаляются примеси, и материал становится однороднее, что повышает его прочность, твердость и гибкость.\n\nНо живые создания – не инструменты.\n\nВ тебе есть сила, потому что ты часто выполняешь функцию молота, и также знаешь, каково это – самому быть гвоздем.\n\nТебе присуща гибкость, потому что ты отстаиваешь свои идеалы, но и уважаешь других, что готовы бороться за свои.\nТебе хватает твердости, потому что ты можешь проявлять и мягкость.\n\nТебя никто не выковал, ты и есть кузнец.', '', 64978),
(305437, 'ruRU', '<Моментий долго, громко и довольно смеется.>\n\nТы даже представления не имеешь.', '', 64978),
(305436, 'ruRU', 'Мм-м... Да, возможно.\n\nВпрочем, возможно, что лучший вывод, который можно было из всего этого сделать, это решать проблемы без бронзы Бесконечности.', '', 64978),
(305435, 'ruRU', '', 'Не переживай об этом. Помощники исследователей приходят и уходят подобно песку, что сыплется в песочных часах.\n\nЗа меня можешь не волноваться. Мы с тобой вместе провели немало важных исследований, но каждому предстоит свой путь, и наши с тобой должны разойтись здесь.\n\nУдачи тебе, $p!', 64978),
(305424, 'ruRU', '', '<Моратари записывает ваши слова.>\n\nИнтересно. Теперь, когда сила артефактов перешла к Азероту, мне интересно, какое у них может быть предназначение в дальнейшем.\n\nМне нужно будет обсудить это с Вечнос.\n\n<Моратари, похоже, перестала обращать на вас внимание, полностью переключившись на свою новую идею.>\n\nА, и спасибо тебе, $p. Наши с тобою ретроспективы очень меня порадовали.', 64978),
(305423, 'ruRU', '', '<Моратари какое-то время изучающе смотрит на вас.>\n\n$p, твое предназначение не определяется одним действием, каким бы оно ни было смелым, самоотверженным и важным.\n\nТвое предназначение – решать за себя, и чтобы за тебя не решали другие.\n\nНуждаемся ли мы в тебе? Нуждается ли в тебе Азерот? Да. Но само по себе то, что ты делаешь для других, то, что им от тебя было нужно, еще не говорит о том, что твоя история подошла к концу. Тебе предстоит проделать еще немалый путь и написать много глав своей...\n\n<Моратари замолкает и затем поправляется.>\n\nЭгм... в смысле, мне показалось, что тебе хотелось бы взяться еще за многое.', 64978),
(305422, 'ruRU', '', 'Мало кто может противиться манящему зову столь могучей силы, $p.\n\nТы сильнее большинства других, и это хорошо.\n\n<Моратари делает какую-то краткую запись.>', 64978),
(304842, 'ruRU', 'Ладно.', 'Ладно.', 64978),
(304705, 'ruRU', '', 'Новые книги поступают ежедневно, так что заглядывай почаще!', 64978),
(304701, 'ruRU', 'Когда фракции вновь объединились под надежной защитой странников бурь, земельники смогли отправить помощь союзной армии Азерота.', '', 64978),
(304700, 'ruRU', 'Новое поколение странников бурь завершило тренировки и поднялось в воздух, чтобы защитить остров Дорн. Они победили колосса и доказали свою доблесть.', '', 64978),
(304699, 'ruRU', 'Титаны подготовили защитные меры, чтобы наказать непокорные творения. Со дна океана поднялась огромная машина – воплощение их гнева.', '', 64978),
(304698, 'ruRU', 'Перед смертью Ансурек получила самый важный урок Бездны – выживают лишь сильнейшие. Слабых не будут ни вспоминать, ни оплакивать.', '', 64978),
(304697, 'ruRU', 'Умирающая Ансурек взывала к Предвестнице о помощи, но Ксал\'атат не сжалилась над королевой. Нерубская правительница не оправдала надежд.', '', 64978),
(304696, 'ruRU', 'Когда армия Азерота низвергла королеву Ансурек и ее служителей, Ксал\'атат даже не подумала вступиться.', '', 64978),
(304695, 'ruRU', 'Ксал\'атат предложила Элрику сделку – она поддержит орден Ночи, а тот разожжет Темное Пламя на башнях Рассвета в Тайносводье.', '', 64978),
(304694, 'ruRU', 'Свет покинул народ арати много лет назад, тьма же обещала силу и свободу. Тогда он основал орден Ночи, набирая союзников среди испуганных и разочарованных.', '', 64978),
(304693, 'ruRU', 'Элрик Лейд когда-то гордился званием фонарщика, но со временем его надежды и вера угасли. Беледар больше не была для него путеводной звездой, а Священное Пламя не воодушевляло.', '', 64978),
(304668, 'ruRU', '', 'Романы, повести, исследовательские записи! Какими бы ни были твои читательские предпочтения, ты всегда найдешь здесь идеальную книгу для себя.', 64978),
(304351, 'ruRU', 'Это чья-та приманка? И на нее можно поймать двадцатифунтовую рыбину?', 'Это чья-та приманка? И на нее можно поймать двадцатифунтовую рыбину?', 64978),
(303982, 'ruRU', 'Приветствую тебя, $n!', '', 64978),
(303889, 'ruRU', 'Ну конечно! Мы же у моря.\n\nНа берег что только не выбрасывает.', '', 64978),
(303886, 'ruRU', 'Мы с ребятами стараемся не смущать местных.\n\nИз вежливости. Не хотим навязываться.', '', 64978),
(303883, 'ruRU', 'Привет, дружище. Хочешь приобрести какую-нибудь редкость?\n\nМы с друзьями путешественники. А перед тобой – наши находки.', '', 64978),
(303853, 'ruRU', 'Лучшие красители – те, что ты изготавливаешь своими собственными руками. Главное – не перепачкаться.\n\nЧем могу помочь?', '', 64978),
(303848, 'ruRU', 'Если ты не можешь изготовить их самостоятельно, попроси помощи у знакомых начертателей или алхимиков. Ну или загляни в аукционный дом в Оргриммаре.', '', 64978),
(303847, 'ruRU', '', 'Ты всегда можешь заглянуть в аукционный дом Штормграда. Предприимчивые алхимики и начертатели наверняка выставляют там на продажу излишки своих товаров. Или поговори со своими знакомыми ремесленникам.', 64978),
(303839, 'ruRU', '', 'Боюсь, ты не сможешь использовать эту покрасочную станцию, если у тебя нет достаточного опыта в алхимии или начертании.', 64978),
(303836, 'ruRU', '', 'Самым основам я тебя обучить могу. Этого будет достаточно для того, чтобы пользоваться этой покрасочной станцией, но и только. Если хочешь мастерски овладеть искусством начертания, тебе нужно вернуться в Штормград. Войди в город через портал, и у торговой лавки, напротив тюрьмы, будет лавка под названием \"Свитки Штормграда\". Тамошние инструкторы знают куда больше меня.\n\nЕсли заблудишься, попроси стражника отметить нужное место на твоей карте.', 64978),
(303835, 'ruRU', '', 'Если у тебя уже есть опыт в алхимии или начертании, у тебя должна быть соответствующая подготовка для изготовления своих собственных красителей. Вставай за стол, и поглядим, что ты умеешь!', 64978),
(303834, 'ruRU', '', 'Хочешь покрасить какую-нибудь обивку? Тогда ты по адресу. Я не рекомендую использовать мои составы для окрашивания волос или меха.\n\nИтак, чем могу служить?', 64978),
(303807, 'ruRU', '', 'Похоже, ты здесь не теряешь времени зря, но, чтобы вывести это дело на новый уровень, без помощи тебе не обойтись.\n\nУ меня тут бригада бездельничает, так что ежели чего – наши молотки к твоим услугам!', 64978),
(303806, 'ruRU', '', 'Хватит спать, увальни! За работу!', 64978),
(303805, 'ruRU', '', 'Мм-м... я вижу, это место еще не готово к дальнейшему улучшению.\n\nПоживи здесь подольше, обвыкнись. Как ты узнаешь, что ты хочешь для своего дома, не исходив его вдоль и поперек и не изучив все его потайные уголки? Ну а как придет время, мы с радостью снесем твои старые стены!', 64978),
(303804, 'ruRU', '', 'Привет, дружище! Ну что, время крушить?', 64978),
(303798, 'ruRU', 'К сожалению, сдается мне, твой дом пока еще не готов к улучшению.\n\nОчень важно как следует изучить свое жилище, прежде чем вносить масштабные изменения. Когда можно будет вывести твой дом на следующий уровень, мы все сделаем и выровняем по высшему разряду.', '', 64978),
(303797, 'ruRU', 'Закатывайте рукава, ребята! Пора за работу!?', '', 64978),
(303795, 'ruRU', 'Я всегда ищу работу, уж какая найдется. Похоже, твоя часть работы сделана, значит, теперь дело за нами.\n\nПросто дай команду, и мои ребята примутся за дело.', '', 64978),
(303793, 'ruRU', 'Добрый день. Чем могу служить?', '', 64978),
(303721, 'ruRU', 'Не топчи меня! Я не шучу!', '', 64978),
(303720, 'ruRU', 'Не подходи!', '', 64978),
(303719, 'ruRU', 'Не. Наступай. На. Меня.', '', 64978),
(303718, 'ruRU', 'Говорю же! Не надо на меня наступать!', '', 64978),
(303717, 'ruRU', 'Держись от меня подальше!', '', 64978),
(303716, 'ruRU', 'Назад! Не подходи близко!', '', 64978),
(303714, 'ruRU', 'Я серьезно!', '', 64978),
(303713, 'ruRU', 'И-и-и! Не топчи меня!', '', 64978),
(303544, 'ruRU', '', 'О... Наверное, тебе пока не по зубам дополнительное испытание.\n\nБольше не хочешь его выполнять?', 64978),
(303543, 'ruRU', '', 'Хочешь придать следующей потасовке дополнительную сложность, |3-6($c)?\n\nМожет, у меня и не найдется для тебя дополнительной награды, но зато ты впечатлишь товарищей, да и зрители будут в восторге!', 64978),
(303293, 'ruRU', 'Конечно. Район гильдии – тут и объяснять нечего. Это район для тебя и участников твоей гильдии.\n\nЕсли же в твоей гильдии участников больше, чем может вместить район, в нем будут созданы дополнительные подразделения, чтобы каждый желающий мог заиметь свой дом.\n\nНу что, продолжим?', '', 64978),
(303290, 'ruRU', '', 'Конечно. Район гильдии – тут и объяснять нечего. Это район для тебя и участников твоей гильдии.\n\nЕсли же в твоей гильдии участников больше, чем может вместить район, в нем будут созданы дополнительные подразделения, чтобы каждый желающий мог заиметь свой дом.\n\nНу что, продолжим?', 64978),
(302804, 'ruRU', 'О... Наверное, тебе пока не по зубам дополнительное испытание.\n\nБольше не хочешь его выполнять?', '', 64978),
(302698, 'ruRU', 'Не скажу, что отдаю что-то даром, скорее даю возможность заработать. Это можешь считать подарком в честь твоего вступления в сообщество. Твой распорядитель тоже кое-что затевает, а пока прими от меня этот скромный презент.\n\nА если беспокоишься за мою собственность, то не стоит. За тысячи лет работы и странствий я собрал внушительную коллекцию. Я бы сказал, что она просто собирает пыль, но в Бездне такое невозможно.\n\nВ любом случае мне приятно видеть эти вещи в руках тех, кто готов найти им применение.', '', 64978),
(302697, 'ruRU', 'Декор – он повсюду. Он все это время был вокруг тебя и никуда не девался, просто до сегодняшнего дня у тебя, как я понимаю, не было места, которое можно было бы им украсить. Ты можешь отыскать поистине невероятные предметы декора в своих приключениях – в настоящем, прошлом и будущем.\n\nКроме того, если ты или кто-то из твоих друзей искусны в ремесле, предметы декора можно изготавливать и самостоятельно.\n\nТакже могу посоветовать тебе обратиться к группам, которым тебе случалось помогать в прошлом. Если ты пользуешься у них высокой репутацией, возможно, они преподнесут тебе что-то в дар.', '', 64978),
(302695, 'ruRU', 'Да, но совсем ненадолго. Услышав, что герои Азерота прибыли на помощь моему народу, я понял, что должен снова взглянуть на К\'ареш. Мне было... нелегко видеть родной мир в таком состоянии.\n\nНо одна мысль подарила мне утешение: на К\'ареше стало ясно, что мой народ и наша культура преодолели все испытания и живы до сих пор. То же можно сказать и о народах Азерота, переживших нашествие Плети, Пылающего Легиона и многие другие бедствия.\n\nВсе творцы когда-нибудь умирают, а дома разрушаются, но мы оставляем свой след в этой вселенной благодаря нашим творениям. Надеюсь, так о нас никогда не забудут.', '', 64978),
(302693, 'ruRU', 'Я просто старый художник, оказавшийся вдали от дома. И... этого дома больше нет. По крайней мере, он уже не такой, каким я его представляю. Возможно, про твой дом можно сказать то же самое. Многие через это проходят в той или иной степени.\n\nКогда К\'ареш был еще цел, мои работы любили и уважали. Но гордиться творениями, которые теперь существуют лишь в воспоминаниях, не так просто. Поэтому я стараюсь об этом не думать.\n\nВзамен я много странствую и познаю чудеса других культур, например твоей. Я ни о чем не жалею.', '', 64978),
(302515, 'ruRU', '', '(вскрики)', 64978),
(302514, 'ruRU', '', '(вскрики)', 64978),
(302513, 'ruRU', '', '(вскрики)', 64978),
(302512, 'ruRU', '', '(тяжелое дыхание)', 64978),
(302511, 'ruRU', '', '(вскрики)', 64978),
(302502, 'ruRU', '', 'Син\'дорай...', 64978),
(302501, 'ruRU', '', 'Элу\'мениэл мал аланн.', 64978),
(302500, 'ruRU', '', 'Син\'дорай...', 64978),
(302499, 'ruRU', '', 'ашал\'аноре.', 64978),
(302498, 'ruRU', '', 'Вендел\'о эрану,', 64978),
(302497, 'ruRU', '', 'Вендел\'о эрану.', 64978),
(302496, 'ruRU', '', '(поет на талассийском)', 64978),
(302349, 'ruRU', 'Шал\'на! Вернись к нам.', '', 64978),
(302348, 'ruRU', '', 'Не-е-ет!', 64978),
(302347, 'ruRU', '', 'Хватит! Довольно!', 64978),
(302346, 'ruRU', '', 'Не могу больше смотреть!', 64978),
(302345, 'ruRU', '', 'Это уже слишком!', 64978),
(302344, 'ruRU', '', 'Хватит!', 64978),
(302343, 'ruRU', '', 'Ужас.', 64978),
(302342, 'ruRU', '', 'Крики...', 64978),
(302341, 'ruRU', '', 'Нет...', 64978),
(302340, 'ruRU', '', '(стоны)', 64978),
(302339, 'ruRU', '', 'Где же ты?', 64978),
(302338, 'ruRU', '', 'Аратор…', 64978),
(302337, 'ruRU', 'Вериса!', '', 64978),
(302336, 'ruRU', '', 'Ронин…', 64978),
(302298, 'ruRU', '', 'Привет!', 64978),
(302297, 'ruRU', '', 'И отправился из моего дома в твой.', 64978),
(302296, 'ruRU', '', 'Он просто тоже хотел вернуться домой!', 64978),
(302295, 'ruRU', '', '(радостный смех)', 64978),
(302294, 'ruRU', 'Я даже не знаю, чем заслужил такую честь.', '', 64978),
(302293, 'ruRU', 'Шэнь-Цзынь Су...', '', 64978),
(302292, 'ruRU', '', 'Чего ты ждешь? Идем!', 64978),
(302291, 'ruRU', '', 'Чо!', 64978),
(302290, 'ruRU', 'Клянусь бородой Шаохао!', '', 64978),
(302289, 'ruRU', 'Где мы?..', '', 64978),
(302288, 'ruRU', 'Не спеши, друг мой!', '', 64978),
(302287, 'ruRU', 'Юй-лун!', '', 64978),
(302286, 'ruRU', '', 'Юй-лун!', 64978),
(302285, 'ruRU', 'Что?', '', 64978),
(302269, 'ruRU', 'Лок\'тар огар!', '', 64978),
(302268, 'ruRU', 'Огры не выстоят перед яростью Орды.', '', 64978),
(302267, 'ruRU', 'Надо избавить Калесгоса от этой участи.', '', 64978),
(302266, 'ruRU', 'Не остановим обряд, Калесгос и его сила будут в их власти!', '', 64978),
(302265, 'ruRU', 'Вот и они.', '', 64978),
(302264, 'ruRU', 'И овладеть его магией!', '', 64978),
(302263, 'ruRU', 'Безмозглые огры хотят провести ритуал.', '', 64978),
(302262, 'ruRU', 'Калесгос где-то рядом. Его пленили в облике дракона.', '', 64978),
(302261, 'ruRU', '', 'За Альянс!', 64978),
(302260, 'ruRU', '', 'Мы не отдадим Калесгоса этим животным.', 64978),
(302259, 'ruRU', '', 'Я буду снимать их чары, пока наши силы не остановят эти грязные ритуалы.', 64978),
(302258, 'ruRU', 'Не остановим обряд, Калесгос и его сила будут в их власти!', '', 64978),
(302257, 'ruRU', 'Вот и они.', '', 64978),
(302256, 'ruRU', 'И овладеть его магией!', '', 64978),
(302255, 'ruRU', 'Безмозглые огры хотят провести ритуал.', '', 64978),
(302254, 'ruRU', 'Калесгос где-то рядом. Его пленили в облике дракона.', '', 64978),
(302210, 'ruRU', 'Зришь в корень. Наверно, придется выкинуть меч, чтобы освободить сумки.', '', 64978),
(302209, 'ruRU', 'Конечно, я могу его поднять. Это же меч.', '', 64978),
(302208, 'ruRU', '<Пифагор на секунду погружается в раздумья.>\n\nТеперь мне просто стыдно сдаваться.', '', 64978),
(302206, 'ruRU', 'Тоже правда.\n\nЯ люблю вздремнуть на новом месте, но меню в них обычно разочаровывает.', '', 64978),
(302204, 'ruRU', 'В такую погоду мне спится лучше всего!', '', 64978),
(302203, 'ruRU', 'Всего три кровати?!\n\nТак и быть, посмотрю. Но если одна из них окажется слишком мягкой, а другая – слишком жесткой, третью извольте застелить в самый раз.\n\nШучу. Я дракон. Мы спим на грудах металла. Кровать сойдет любая, лишь бы была.', '', 64978),
(302201, 'ruRU', '', 'Я тоже так думаю.', 64978),
(302200, 'ruRU', '', 'Чего? Я просто хотела задать вопрос.\n\nПочему сразу любовь-морковь? Вообще не понимаю, причем тут поцелуи.', 64978),
(302199, 'ruRU', '', 'Думаешь?\n\nТо есть конечно. Ага. Супер. Я просто хотела задать вопрос, ничего такого.', 64978),
(302198, 'ruRU', '', 'Она умеет впечатлить, это точно.', 64978),
(302197, 'ruRU', '', 'Ну, с моими копытами никакая обувь не нужна. Но корона мне пошла бы.', 64978),
(302196, 'ruRU', '', 'О-о-о! Всегда хотела одеться как хулиганка.', 64978),
(302192, 'ruRU', 'Красота эльфов Бездны поразительна.\n\nНаверное, стоит ненадолго наведаться – поздно ночью... Чтобы никому не мешать, конечно.', '', 64978),
(302191, 'ruRU', 'Сокровища, ха! Ну нет – спускаться в самые недра за немыслимыми богатствами и потерянными артефактами? По-моему, просто абсурд.\n\nСтрашно даже представить.', '', 64978),
(302190, 'ruRU', 'О, археология. Да-да. Совершенно законный метод... кхм... поиска артефактов и... э-э... их исследования. Именно.', '', 64978),
(302180, 'ruRU', 'Опа, дельная мысль. Я уже тыщу лет не рыбачил.', '', 64978),
(302178, 'ruRU', 'Целая планета, говоришь? Ну это уже перебор.\n\nТут нужен калибр миллиметров двадцать, чтоб ее хотя б поцарапать, не то что завалить.', '', 64978),
(302175, 'ruRU', 'Да уж, пожалуй... Мне было бы страшно лезть в драку с титаном.', '', 64978),
(302171, 'ruRU', 'Эрию никогда не приходило в голову утилизировать целый мир. Куда девать утиль, если утилизировать место, где хранится весь утиль?\n\nЭрию надо прилечь.', '', 64978),
(302170, 'ruRU', 'Ха! Эрий оценил идею превратить корабль Легиона в утиль мана-бомбами. Очень эффективно.', '', 64978),
(302169, 'ruRU', 'Эрию интересно посмотреть на целую разрушенную деревню, но грустно думать о беженцах.', '', 64978),
(302158, 'ruRU', '', 'Скажи мне, $p, что сталось с Сурамаром и повстанцами? Ты же помнишь, что там было. Какие уроки мы можем извлечь из твоей истории?', 64978),
(302132, 'ruRU', 'Ты найдешь их в Убежище гладиатора.', 'Ты найдешь их в Убежище гладиатора.', 64978),
(302131, 'ruRU', 'Найдешь их на аллее Чести. Давай отмечу место на карте.', 'Найдешь их на аллее Чести.', 64978),
(302130, 'ruRU', 'Поищи-ка на аллее Чести.', 'Поищи-ка на аллее Чести.', 64978),
(302129, 'ruRU', 'Тренировочные манекены можно найти во внешней части Старого города.', 'Тренировочные манекены можно найти во внешней части Старого города.', 64978),
(302029, 'ruRU', 'Э-э... спасибо. Бери планы... и не говори другим, что я тут делал. Лады?', '', 64978),
(301952, 'ruRU', 'Хочешь придать следующей потасовке дополнительную сложность, |3-6($c)?\n\nМожет, у меня и не найдется для тебя дополнительной награды, но зато ты впечатлишь товарищей, да и зрители будут в восторге!', '', 64978),
(301890, 'ruRU', 'Может, что-то и слышал, может, и нет.', 'Может, что-то и слышала, может, и нет.', 64978),
(301889, 'ruRU', 'Амбиции без должных финансов ни к чему не приведут. Особенно с этой ареной.', 'Амбиции без должных финансов ни к чему не приведут. Особенно с этой ареной.', 64978),
(301888, 'ruRU', 'Да ладно тебе. Где твои амбиции?', 'Да ладно тебе. Где твои амбиции?', 64978),
(301887, 'ruRU', 'Но даже если так, нам все равно не видать приглашения.', 'Но даже если так, нам все равно не видать приглашения.', 64978),
(301885, 'ruRU', 'Кстати об этом...', 'Кстати об этом...', 64978),
(301883, 'ruRU', 'А ты знаешь, что арена \"Морд\'Бой\" снова открыта?', 'А ты знаешь, что арена \"Морд\'Бой\" снова открыта?', 64978),
(301808, 'ruRU', 'А, здравствуй, |3-6($c). Я тебя не заметил. Это, конечно, не важно, но как долго ты нас слушаешь?', 'А, здравствуй, |3-6($c). Я тебя не заметила. Это, конечно, не важно, но как долго ты нас слушаешь?', 64978),
(301806, 'ruRU', 'Приветствую, |3-6($r). Мне никто ничего не советовал, а я ничего не советовал другим.', 'Приветствую, |3-6($r). Мне никто ничего не советовал, а я ничего не советовала другим.', 64978),
(301761, 'ruRU', 'и спасите Нагорье Арати!', '', 64978),
(301760, 'ruRU', 'Поддержите бойцов Орды и Альянса.', '', 64978),
(301759, 'ruRU', 'и готовы присоединиться к бою.', '', 64978),
(301758, 'ruRU', 'Вы ответили на призыв о помощи', '', 64978),
(301757, 'ruRU', 'Павший Молот несет большие потери.', '', 64978),
(301749, 'ruRU', 'Тебе что-то надо, |3-6($c)?', '', 64978),
(301684, 'ruRU', 'Кстати об этом...', 'Кстати об этом...', 64978),
(301683, 'ruRU', 'Амбиции без должных финансов ни к чему не приведут. Особенно с Бизмо.', 'Амбиции без должных финансов ни к чему не приведут. Особенно с Бизмо.', 64978),
(301682, 'ruRU', 'Да ладно тебе. Где твои амбиции?', 'Да ладно тебе. Где твои амбиции?', 64978),
(301681, 'ruRU', 'Но даже если так, нам все равно не видать приглашения.', 'Но даже если так, нам все равно не видать приглашения.', 64978),
(301680, 'ruRU', 'Может, что-то и слышал, может, и нет.', 'Может, что-то и слышала, может, и нет.', 64978),
(301679, 'ruRU', 'А ты знаешь, что потасовочная \"У Бизмо\" снова открыта?', 'А ты знаешь, что потасовочная \"У Бизмо\" снова открыта?', 64978),
(301673, 'ruRU', 'Приветствую, |3-6($r). Мне никто ничего не советовал, а я ничего не советовал другим.', 'Приветствую, |3-6($r). Мне никто ничего не советовал, а я ничего не советовала другим.', 64978),
(301663, 'ruRU', 'Тебе что-то надо, |3-6($c)?', '', 64978),
(301554, 'ruRU', 'А, здравствуй, |3-6($c). Я тебя не заметил. Это, конечно, не важно, но как долго ты нас слушаешь?', 'А, здравствуй, |3-6($c). Я тебя не заметила. Это, конечно, не важно, но как долго ты нас слушаешь?', 64978),
(301471, 'ruRU', 'Твое большое сердце целый мир могло объять. Себя ты не жалел, измученный, был непреклонен, и нас ты не переставал от боли защищать. Но вот остановился ты в объятиях покоя.\n\nТак бегал, так резвился! Играл, покуда мог дышать. Твоя крепчайшая любовь тепло нам всем дарила, и жажду близости твою никто не мог унять. Ты рядом был, какие бы удары нам судьба ни наносила.\n\nМы дали тебе малость – ты отдал нам всего себя. Терять тебя так больно, и ты платы за любовь достоин. О друг мой милый, любовь к тебе нас изменила навсегда. Твой долг теперь исполнен. Покойся, маленький наш воин.', '', 64978),
(301421, 'ruRU', 'По просьбе визиря Андуин и Аллерия узнали много нового о жизни нерубов и королеве Ансурек.', '', 64978),
(301420, 'ruRU', 'Андуин пропал, но Аллерия не теряла надежду отыскать его... и таинственное создание, которое внезапно пришло героям на помощь.', '', 64978),
(301419, 'ruRU', 'Ферин, Андуин и герой отразили нападение нерубов. Ферин решила зажечь ближайшую башню Рассвета, чтобы помочь другим арати.', '', 64978),
(301333, 'ruRU', 'А с другой стороны выступит ужасный и цветастый... Санни!', '', 64978),
(301332, 'ruRU', '', 'А с другой стороны выступит ужасный и цветастый... Санни!', 64978),
(301084, 'ruRU', 'От всего сердца приветствую, дружище! Как наша община может тебе помочь?', '', 64978),
(301083, 'ruRU', '', 'Здравствуй и добро пожаловать в наш район!', 64978),
(300996, 'ruRU', 'Издавна по всему Азероту ходило немало историй о Предвестнице. Но самая важная из них, повествующая о ней и Темном сердце, до сих пор не имеет конца.', '', 64978),
(300989, 'ruRU', 'Разумеется. Когда мы встретились впервые, я сказал тебе, что не могу напрямую влиять на временную линию.\n\nИ начнем с того, что никакого знания у тебя изначально не было. Ты всего лишь орудие в моих руках. Лазейка для меня, если можно так выразиться, но ее нужно будет закрыть.', '', 64978),
(300956, 'ruRU', '<Таинственная фигура тяжко вздыхает.>\n\nНу хорошо. Меня зовут Анакрон. Я сотрудничаю с группой так называемых искателей разума. Среди моих клиентов те, кому требуются мои таланты по части обмена ценностями меж временными линиями. Когда у меня нет неотложных дел, я развлекаю себя тем, что создаю головоломки для тех, кому интересно разыскивать и разгадывать их.\n\nБольше ты не произнесешь ни слова и никому не расскажешь об этом. Наши дела здесь с тобой закончены.', '', 64978),
(300932, 'ruRU', '', '<Моратари записывает ваши слова.>\n\nЧто именно ты имеешь в виду?', 64978),
(300924, 'ruRU', 'Завладев Темным сердцем и силой самого Пространствуса, Ксал\'атат исчезла, оставив героев гадать, где и когда она нанесет следующий удар.', '', 64978),
(300923, 'ruRU', 'Итак, каким бы привлекательным ни было предложение, а ситуация отчаянной, в конце концов всегда выигрывает только Ксал\'атат.', '', 64978),
(300922, 'ruRU', 'Пространствус был повержен, но Страннику открылась страшная истина – этот урок еще до него усвоили Галливикс, королева Ансурек, Элрик Лейд и верховный глашатай Эйрих.', '', 64978),
(300920, 'ruRU', 'Таинственный союзник послал Страннику видение о гибели, грозящей обитателям К\'ареша... и всему сущему.', '', 64978),
(300919, 'ruRU', 'Галливикс добился контроля над гоблинами Нижней Шахты и проводил эксперименты с черной кровью. Это привлекло внимание Газлоу. Он обратился к Аллерии, зная о ее охоте на Ксал\'атат, и отправился с эльфийкой в город, где их застала врасплох атака эфириалов.', '', 64978),
(300918, 'ruRU', 'Прядильщица наделила героя скрывающими феромонами, позволяющими беспрепятственно пересечь город... при условии, что тот не попадется страже.', '', 64978),
(300917, 'ruRU', 'Аллерия, Андуин и Ферин отправились еще дальше вглубь мира, стремясь настигнуть Ксал\'атат, но там их поджидали нерубы.', '', 64978),
(300916, 'ruRU', 'Услышав знакомое слово \"Арати\", Андуин Ринн спустился вглубь подземелий Азерота.', '', 64978),
(300914, 'ruRU', 'И все же она была намерена заручиться поддержкой своего народа и воссоединить Совет.', '', 64978),
(300913, 'ruRU', '', 'Горе? Но ведь вы одержали победу. Вы спасли Азерот. Разве это не повод для...\n\n<Моратари умолкает, осознавая, что эмоции бывает трудно выразить словами.>\n\n...радости?', 64978),
(300910, 'ruRU', '', 'Это просто великолепно, $p! Расскажи подробнее!', 64978),
(300909, 'ruRU', '', 'Волнение? Любопытно. Можешь немного развернуть свой ответ?', 64978),
(300908, 'ruRU', '', 'Облегчение. Физическое? Душевное? Эмоциональное?\n\n<Моратари готовится записать ваш ответ.>\n\nЧем больше подробностей, тем лучше. Исключительно в исследовательских целях, разумеется.', 64978),
(300907, 'ruRU', '', 'Какой меч, ты о чем?\n\n<Моратари недоуменно оглядывается, высматривая на горизонте меч Саргераса.>', 64978),
(300906, 'ruRU', '', '<Моратари ободряюще смотрит на вас и говорит тихим голосом.>\n\nТак и есть, $p. Мы делаем все это именно потому, что Вечнос не все равно. Порою даже слишком.', 64978),
(300905, 'ruRU', '', 'Вот это настрой, $p.\n\n<Моратари готовится записывать.>\n\nОбъект совершенно не задумывается о будущем.\n\n<Моратари поднимает голову и лучезарно улыбается.>\n\nСпасибо тебе за твои воодушевляющие слова.', 64978),
(300904, 'ruRU', '', 'Надежда есть всегда, $p.\n\n<Моратари готовится записывать.>\n\nОбъект выражает чувства безнадежности и отчаяния.\n\n<Моратари поднимает голову и лучезарно улыбается.>\n\nСпасибо тебе за твои соображения.', 64978),
(300903, 'ruRU', '', 'Ты этого заслуживаешь, $p. Я тебя не тороплю. Я буду здесь, когда понадоблюсь тебе.\n\n<Моратари на секунду задумывается.>\n\nЕсли понадоблюсь.', 64978),
(300866, 'ruRU', 'Мебель-то практически в любом жилище найдется, ха-ха!\n\nА вот если тебя интересует декор, обратиться лучше к тем, у кого ты на хорошем счету. Вдруг у них перед тобой есть должки?\n\nЕсли знаешь какого-нибудь опытного ремесленника, он может сделать для тебя что-нибудь на заказ.\n\nМожет оказаться и так, что какие-то предметы декора уже ждут тебя в награду за твои достижения.\n\nТакова магия декора!', '', 64978),
(300864, 'ruRU', 'Здравствуй! С тобой говорит Лап До из \"Дивного декора Фредерика\".', '', 64978),
(299925, 'ruRU', 'Добро пожаловать домой!', 'Добро пожаловать домой!', 64978),
(299652, 'ruRU', '', 'Да. А что, тебя не волнует, как выглядит твой дом? Какой у него колорит? Как по мне, орочий декор украсит любое жилище. И я могу с этим помочь.', 64978),
(299651, 'ruRU', '', 'Добро пожаловать, командир. У меня лучшее оружие, броня и декор для дома во всем Ашране.$b$bДай знать, если понадобится моя помощь.', 64978),
(299641, 'ruRU', 'Да. Почему обитатели твоего мира все время этому удивляются? Есть не так много мест важнее дома, командир. А дренейский декор украсит любое жилье.', '', 64978),
(299633, 'ruRU', 'Какая забота, $p!\n\nНе печалься, ведь с самого начала было ясно, что мы здесь не навсегда. Важно сохранить воспоминания о нас не только в памяти, но и в сердце.\n\nРодной дом – там, где сердце, и поэтому ты, естественно наполняешь его тем, что напоминает тебе о тех, с кем ты расстался.\n\nВзгляни еще раз – может, в моей коллекции найдется такая вещица, которую стоит взять на память.', '', 64978),
(299629, 'ruRU', 'Здесь тебя ждет теплый прием, путешественник во времени.\n\nИзучи мои уникальные возможности по улучшению дома. Каждая из них тематически соответствует и времени, и месту.', '', 64978),
(299165, 'ruRU', 'Когда герои призвали верховного глашатая к ответу, он бежал к Машине пробуждения. Магни, Дагран и Мойра отправились за ним.', '', 64978),
(299164, 'ruRU', 'От жителей Таэллока и местного бригадира уже несколько недель не было вестей, но верховный глашатай Эйрих препятствовал любым расследованиям. Магни и Дагран решили узнать, что произошло.', '', 64978),
(299163, 'ruRU', 'До своего изгнания Бринте служила глашатаем механизмов земельников. Ее любопытство по отношению к титанам и их эдиктам разгневало верховного глашатая Эйриха.', '', 64978),
(299160, 'ruRU', 'Краткий пересказ – это способ ознакомиться с событиями из прошлого Азерота в последовательном порядке. \n\nОбратившись к собранию летописей, вы можете увидеть эти события так, словно сами в них участвовали.', 'Краткий пересказ – это способ ознакомиться с событиями из прошлого Азерота в последовательном порядке. \n\nОбратившись к собранию летописей, вы можете увидеть эти события так, словно сами в них участвовали.', 64978),
(299157, 'ruRU', 'Земельники отразили атаку нерубов, а Освобожденные занялись ремонтом Артерии. Но странников бурь ждала новая напасть: под угрозой оказалось Гнездовье. Бэлгрим отправился туда, чтобы узнать, в чем дело.', '', 64978),
(299153, 'ruRU', 'Вестник Магни Бронзобород попытался напрямую связаться с Азерот, но видение было такой силы, что Магни потерял сознание. Союзники переправили его в Даларан.', '', 64978),
(298647, 'ruRU', '', 'Местные прозвали этот холм Малое Гнездо. Все потому, что сюда слетаются стаи грифонов.', 64978),
(297061, 'ruRU', '', 'Не получается найти подходящий участок?\n\nКак сертифицированный агент, я помогу тебе с выбором и подберу еще несколько участков, которые могут тебя заинтересовать.\n\nБыть может, ты хочешь основать новый район для своих друзей или товарищей по гильдии? Я могу помочь и с этим.\n\nА если тебе хочется еще немного подумать, тоже не беда. Я отправлю тебя назад, и ты сможешь в любой момент сюда вернуться.', 64978),
(297060, 'ruRU', '', 'Не волнуйся насчет документов. Я займусь ими, а ты можешь полностью сосредоточиться на развитии района. Какой район ты собираешься создать?', 64978),
(297059, 'ruRU', '', 'Добро пожаловать домой! То есть, надеюсь, скоро здесь будет твой дом.\n\nЕсли ты не прочь обзавестись жильем, посмотри вокруг и поищи свободный участок. Когда что-нибудь приглянется, приобрети участок, воспользовавшись знаком \"Продается\".\n\nЕсли понадобится помощь с поисками, обращайся ко мне – я покажу тебе много подходящих вариантов.', 64978),
(297057, 'ruRU', '', 'Не можешь найти подходящий участок? Рассмотри другие варианты с помощью поиска жилья.\n\nВозможно, собственность твоей мечты скрывается где-то в списках. Я с радостью тебе все покажу, только имей в виду, что в других районах у тебя будут другие соседи.\n\nЧто скажешь? Поищем участок в другом месте?', 64978),
(297053, 'ruRU', '', 'Здравствуй! Я с радостью помогу тебе по всем жилищным вопросам.', 64978),
(297052, 'ruRU', '', 'С удовольствием составлю тебе компанию. Каждый раз, когда я прогуливаюсь по городу, я замечаю что-то новое. Мне уже не терпится поделиться с тобой всем, что я узнала.', 64978),
(297050, 'ruRU', 'Нет начинания благороднее, чем развитие общины. Какого рода район тебе хотелось бы создать?', '', 64978),
(297049, 'ruRU', 'Если не получается найти хороший участок, воспользуйся поиском жилья и посмотри в других общинах.\n\nДухи всегда направляют нас, они помогут отыскать свободное место, которое придется тебе по сердцу. Только учти, что там тебя будут ждать уже другие соседи.\n\nХочешь поискать в другом месте?', '', 64978),
(297048, 'ruRU', 'До чего чудесный день! Давай поищем для тебя что-нибудь подходящее. А если нам попадутся интересные места – станет еще лучше.', '', 64978),
(297047, 'ruRU', 'Трудно выбрать идеальный дом?\n\nЕсли не удается найти свободный участок, духи постараются тебе помочь.\n\nА если хочешь основать собственную общину для друзей или товарищей по гильдии, мы поможем и с этим.\n\nМы понимаем, что выбор дома – дело непростое. Если ты пока не можешь решиться, просто скажи, и мы отправим тебя обратно.', '', 64978),
(297046, 'ruRU', 'Добро пожаловать в нашу общину!\n\nИщешь место, где можно повесить шляпу или шлем? Погляди вокруг и присмотри себе свободный участок. Когда найдешь хорошее место, приобрети его, воспользовавшись знаком \"Продается\".\n\nА если не получится что-то найти, просто скажи: мы подыщем для тебя другие варианты.', '', 64978),
(297045, 'ruRU', 'От всего сердца приветствую, дружище! Как наша община может тебе помочь?', '', 64978),
(297001, 'ruRU', 'Мятежники победили Галливикса... но потеряли Темное сердце. Совсем скоро Аллерия получила послание от своего наставника, Странника. Давным-давно его родной мир К\'ареш был уничтожен Пространствусом, кошмарным созданием из Бездны.', '', 64978),
(297000, 'ruRU', 'Темное сердце было расколото, но Ксал\'атат знала, что гоблины Нижней Шахты способны его восстановить. Она убедила Джастора Галливикса пойти на сделку с Бездной.', '', 64978),
(296998, 'ruRU', 'Прядильщица собирала союзников. Генерал Ануб\'азал перешел на ее сторону, и герой отправился на поиски Андуина и нового пособника Прядильщицы, визиря, в Город Нитей.', '', 64978),
(296997, 'ruRU', 'Как и верховный глашатай земельников, Элрик Лейд заключил сделку с Ксал\'атат, предав свой народ. Вера арати пошатнулась – но когда Ферин вернула Свет, она вспыхнула вновь.', '', 64978),
(296996, 'ruRU', 'Андуин вновь встретился с Аллерией. Та все еще охотилась на Ксал\'атат.', '', 64978),
(296995, 'ruRU', 'Герои не могли попасть к Пространствусу с одной лентой реши. Для победы над повелителем Бездны нужно было больше. Странник попросил ленту у Ве\'нари, давней союзницы из организации Сплетение. Но та не собиралась отдавать ее просто так.', '', 64978),
(296983, 'ruRU', 'Аллерия беспокоилась не зря. Пустынники перешли на другую сторону, как только появился правитель Салхадаар и призвал их к действию. Но необходимые ленты реши были собраны. Герои приготовились к битве с Пространствусом.', '', 64978),
(296981, 'ruRU', 'Восстановление Артерии почти завершено. Адельгонн вернулась в Дорногал и встретилась с Мерриксом, чтобы обсудить дальнейшие действия.', '', 64978);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(296980, 'ruRU', 'Земельники нашли возможный способ восстановить Артерию, но устранить раскол между их фракциями было гораздо сложнее.', '', 64978),
(296979, 'ruRU', 'Когда Аллерия начала преследовать Ксал\'атат, многим жителям Азерота стали являться таинственные видения. Впоследствии их назвали Сияющей Песнью.', '', 64978),
(296977, 'ruRU', 'Верховный маг Кадгар вызвал Аллерию Ветрокрылую в Даларан. Он получил тревожные вести о таинственном недруге, известном как Предвестница, и попросил эльфийку узнать больше.', '', 64978),
(296856, 'ruRU', 'Вы представляете благородный Альянс – союз королевств Азерота, которые сражаются за идеалы доблести и справедливости.', '', 64978),
(296846, 'ruRU', 'Вы – воин могучей Орды: союза множества разных народов, объединенных любовью к свободе, чести и славе.', '', 64978),
(296828, 'ruRU', 'Аллерия и Андуин бежали из Города Нитей, но королева Ансурек объявила надземному миру войну, и ее надо было срочно остановить. Тралл и Джайна прибыли с подкреплением от Альянса и Орды и вместе с земельниками приготовились к предстоящей битве.', '', 64978),
(296827, 'ruRU', 'Орвейна была не единственным новым союзником. Пока Аллерия искала Андуина, к герою обратилась вдова Арак\'най, также известная как Прядильщица, с предложением объединить усилия.', '', 64978),
(296826, 'ruRU', 'Фонарщик, перешедший на сторону зловещего ордена Ночи, осквернил башню Рассвета – бывший маяк Священного Пламени.', '', 64978),
(296825, 'ruRU', 'Бринте стала новым лидером глашатаев механизмов, и Совет заработал в полном составе. Сделка с Ксал\'атат сорвалась, и Машина пробуждения перестала создавать скардинов. Пробудилось новое поколение земельников.', '', 64978),
(296823, 'ruRU', 'Лент реши все еще не хватало. Ксал\'атат задумала использовать пустынников – обездоленных кочевников, оставшихся на К\'ареше. Обретя надежду на восстановление родного мира, они согласились помочь.', '', 64978),
(296819, 'ruRU', 'Вместе троица попыталась попасть в манагорн Омега, где Пространствус ждал своего часа. Но путь туда был непрост.', '', 64978),
(296811, 'ruRU', 'Неужели Аспект Магии так легко подчинится врагу? Борись, Калесгос!', '', 64978),
(296772, 'ruRU', 'Герои очистили Гнездовье... но цена победы была высока. Бэлгрим поспешил в медоварню, чтобы положить конец нашествию нерубов.', '', 64978),
(296770, 'ruRU', 'Мойра встретилась с надзирателем Совета Мерриксом, а Джайна, Тралл, Андуин и Аллерия начали обдумывать следующий шаг.', '', 64978),
(296769, 'ruRU', 'Даларан был разрушен, и герои Азерота обратились за поддержкой к земельникам. Прибыв в столицу земельников Дорногал, они обнаружили, что Артерия – путь, ведущий в Гулкие глубины под городом – повреждена и захвачена нерубами.', '', 64978),
(296755, 'ruRU', 'Похоже, под всем этим хламом скрывался хороший дом. Но если захочешь вернуть какой-то предмет, найди его в сундуке.', '', 64978),
(296742, 'ruRU', 'Начнешь обустраивать дом? Поскорей бы увидеть, как он будет выглядеть.', '', 64978),
(296741, 'ruRU', 'Загляни в домашний сундук и вдохновись. Достань приглянувшийся предмет и размести его, где хочешь.', '', 64978),
(296740, 'ruRU', 'Прислушайся к земле, стенам и потолку. Твое сердце подскажет, где что разместить.', '', 64978),
(296739, 'ruRU', 'У тебя все задатки отличного художника-декоратора. Что ж, дерзай.', '', 64978),
(296738, 'ruRU', '', 'Пора обустроить дом! Поскорее бы посмотреть, как ты тут все украсишь.', 64978),
(296737, 'ruRU', '', 'В твоем домашнем сундуке чего только нет. Доставай все, что нравится, и расставляй по местам.', 64978),
(296736, 'ruRU', '', 'Полы, стены и даже потолок – твое поле для творчества. Размещай, что хочешь – где хочешь.', 64978),
(296735, 'ruRU', '', 'Похоже, ты осваиваешь основы декора. С радостью посмотрю, как ты будешь творить в будущем.', 64978),
(296732, 'ruRU', '', 'Это отличный выбор! Мне не терпится увидеть, что ты сделаешь с этим участком.', 64978),
(296731, 'ruRU', '', 'Да, тут не помешает ремонт и уборка. Но это несложно: если видишь что-то лишнее, просто убери в сундук.', 64978),
(296729, 'ruRU', '', 'Твой дом все больше похож на уютное гнездышко. А если передумаешь, убранные предметы будут доступны в домашнем сундуке.', 64978),
(296728, 'ruRU', '', 'Теперь здесь все чисто и аккуратно. Повезло, что в этих завалах не было несущих конструкций.', 64978),
(296725, 'ruRU', 'У этого участка хорошая энергетика. Он тебе подходит. Посмотрим, как ты его обустроишь.', '', 64978),
(296724, 'ruRU', 'Этому дому просто нужно немного заботы. Если захочешь прибраться, возьми лишние вещи и убери в сундук.', '', 64978),
(296721, 'ruRU', 'Да, теперь дом выглядит гораздо опрятнее. А пыль скоро осядет.', '', 64978),
(296719, 'ruRU', 'Боюсь, этот участок продан. Но если он нравится тебе больше всего, мы можем помочь. Только скажи.', '', 64978),
(296718, 'ruRU', 'Этот участок занят. Но мы можем найти для тебя такой же в другом месте.', '', 64978),
(296717, 'ruRU', 'Дай мне знать, если тебе по душе именно этот участок.', '', 64978),
(296716, 'ruRU', 'Время идет, а тебе так и не удалось выбрать подходящий дом? Скажи, если хочешь обсудить все варианты.', '', 64978),
(296715, 'ruRU', 'Тебе трудно выбрать участок? Только скажи, и я помогу.', '', 64978),
(296713, 'ruRU', '', 'Похоже, кто-то уже выкупил этот участок. Однако мы можем кое-что сделать. Дай мне знать, если хочешь это обсудить.', 64978),
(296712, 'ruRU', '', 'Этот участок продан. Жаль, но ничего страшного. Обратись ко мне, и я тебе помогу.', 64978),
(296711, 'ruRU', '', 'Скажи мне, если точно хочешь выбрать этот участок.', 64978),
(296710, 'ruRU', '', 'Прошло уже много времени. Тебе так ничего и не приглянулось? Дай мне знать, если хочешь обсудить все варианты.', 64978),
(296709, 'ruRU', '', 'Не получается выбрать участок? Обращайся, и я постараюсь помочь.', 64978),
(296708, 'ruRU', '', 'А, будущий домовладелец! Добро пожаловать в наш район!', 64978),
(296707, 'ruRU', '', 'Люблю прогуливаться по городу. Посмотрим, какие тут есть свободные участки.', 64978),
(296705, 'ruRU', '', 'А если появятся вопросы или ты не найдешь ничего подходящего, обращайся ко мне.', 64978),
(296704, 'ruRU', 'Добро пожаловать! Хочешь стать частью нашей общины?', '', 64978),
(296703, 'ruRU', 'Здесь найдется место для каждого. Давай и тебе что-нибудь подберем.', '', 64978),
(296701, 'ruRU', 'А если ничего не найдешь или захочешь что-то спросить, только скажи.', '', 64978),
(296700, 'ruRU', 'Здесь есть плодородная почва и чистая вода. Все условия для процветания и развития нашей общины.', '', 64978),
(296699, 'ruRU', 'На острове напротив пылает неугасающий костер. Его свет озаряет как наши самые печальные церемонии, так и самые радостные торжества.', '', 64978),
(296698, 'ruRU', 'Через эти доки приходят и уходят продукты, скот и товары ремесленников. Мы делимся всем, что получаем, и отдаем в той же мере.', '', 64978),
(296697, 'ruRU', 'Эти утесы укрывают текущие внизу ключи. Их вода богата минералами и полезна для здоровья, особенно наших друзей земельников.', '', 64978),
(296696, 'ruRU', 'Здесь пустыня расцветает. Шаманы говорят, что жизнь тут только зарождается, совсем как наша новая община.', '', 64978),
(296695, 'ruRU', 'Это наветренная сторона острова. Здешние деревья стали первыми свидетелями прибытия кораблей Орды на берега Калимдора.', '', 64978),
(296694, 'ruRU', '', 'В ранних хрониках острова упоминается потерявший память дворф, выброшенный сюда прибоем. Его имя до нас не дошло, но мы знаем, что он возвел этот мост.', 64978),
(296693, 'ruRU', '', 'Маяк на утесе – одна из самых значимых достопримечательностей острова. Это первое, что встречает корабли, прибывающие в порт Штормграда.', 64978),
(296692, 'ruRU', '', 'На острове всегда тщательно велся учет усопших. Здесь жило более пятидесяти поколений. Имена встречаются самые интересные.', 64978),
(296691, 'ruRU', '', 'Посевы меняются с каждым сезоном, но эти поля, сады и деревья были здесь еще до основания Штормграда.', 64978),
(296690, 'ruRU', '', 'В своем дневнике Фальдир писал о том, что он нашел здесь тихую гавань. Этот остров стал важным опорным пунктом для людей, осваивающих южные земли.', 64978),
(296640, 'ruRU', 'Я постараюсь сорвать ритуал, но лучше не мешкай. Не хочу снова оказаться в плену.', '', 64978),
(296537, 'ruRU', '', 'Сначала позаботимся о раненых, а затем решим, что делать дальше.', 64978),
(295918, 'ruRU', '', 'Вот, он опять за свое! Если прервешь его атаки, он перезапустится и все будет исправлено.', 64978),
(295548, 'ruRU', 'Еще не все... Я выберусь! Нападу снова!', '', 64978),
(295520, 'ruRU', 'Стромгард осаждают враги.', '', 64978),
(295519, 'ruRU', 'как появилась новая угроза, погрузившая их в хаос.', '', 64978),
(295518, 'ruRU', '<Несмотря на все, что случилось, Угоу все так же невозмутим. Его присутствие даже вам придает спокойствия.>', '', 64978),
(295418, 'ruRU', 'Однако едва эти земли начали привыкать к мирной жизни,', '', 64978),
(295417, 'ruRU', 'но сейчас между Ордой и Альянсом действует хрупкое перемирие.', '', 64978),
(295416, 'ruRU', 'Нагорье Арати было оспариваемой территорией,', '', 64978),
(295179, 'ruRU', '<Перед вами парит тяжелый фолиант. Что вы хотите узнать?>', '<Перед вами парит тяжелый фолиант. Что вы хотите узнать?>', 64978),
(294792, 'ruRU', 'Пять циклов. Один сменяет другой, но рано или поздно все повторяется. Словно маназмей, который жрет свой собственный хвост.', '', 64978),
(294784, 'ruRU', 'Чем я торгую? Тем, что даровал мне аспект Обмена. Сегодня у меня эти вещи, завтра другие.', '', 64978),
(294675, 'ruRU', 'Чего по мне стучишь? Постучись лучше к соседям.', '', 64978),
(294674, 'ruRU', 'Хочешь в клуб барабанщиков? Будем стучать тебе по макушке.', '', 64978),
(294673, 'ruRU', 'Для всех место найдется.', '', 64978),
(294672, 'ruRU', 'Хороший сегодня денек.', '', 64978),
(294671, 'ruRU', 'В общине важно единство.', '', 64978),
(294670, 'ruRU', 'Цени ближних.', '', 64978),
(294669, 'ruRU', 'Неси другим добро.', '', 64978),
(294668, 'ruRU', 'Готов помочь.', '', 64978),
(294667, 'ruRU', 'Я никуда не денусь.', '', 64978),
(294666, 'ruRU', 'У нас общее дело.', '', 64978),
(294665, 'ruRU', '', 'Что принесет новый день?', 64978),
(294664, 'ruRU', '', 'Пусть все услышат твой голос.', 64978),
(294663, 'ruRU', '', 'Перемены делают нас сильнее.', 64978),
(294662, 'ruRU', '', 'У нас общее дело.', 64978),
(294661, 'ruRU', '', 'Радуйся всему новому.', 64978),
(294660, 'ruRU', '', 'Наши сердца открыты.', 64978),
(294659, 'ruRU', '', 'Новый день начинается здесь.', 64978),
(294658, 'ruRU', '', 'Мы всем рады.', 64978),
(294657, 'ruRU', '', 'Если тебе совсем нечего делать, всегда найдется мусор, который нужно убрать.', 64978),
(294656, 'ruRU', '', 'Девятая статья товарищества собственников запрещает доставать соседей.', 64978),
(294655, 'ruRU', 'План уже готов и отправлен на рассмотрение. Поздно что-то менять!', '', 64978),
(294654, 'ruRU', 'Хочешь свободную планировку? Как тебе Бездна?', '', 64978),
(294653, 'ruRU', 'Дорожи своим домом.', '', 64978),
(294652, 'ruRU', 'Претворяй мечты в жизнь.', '', 64978),
(294651, 'ruRU', 'Искусство – бесконечный процесс.', '', 64978),
(294650, 'ruRU', 'Важное в малом.', '', 64978),
(294649, 'ruRU', 'Больше не нужно скитаться.', '', 64978),
(294648, 'ruRU', 'Каждый кирпич – своя история.', '', 64978),
(294647, 'ruRU', 'Всегда твори осмысленно.', '', 64978),
(294646, 'ruRU', 'Важна и красота, и практичность.', '', 64978),
(294644, 'ruRU', '', 'Вот вы где. Где вы пропадали? И что с тобой, Аратор? Ты будто увидел приведение.', 64978),
(294640, 'ruRU', 'Мы нашли ее, мама. Она... не такая, как я представлял.', '', 64978),
(294638, 'ruRU', 'Лучшие хмелевары нашего острова снова взялись за дело. Что же Чэнь Буйный Портер привез из своих странствий на этот раз?\n\nЯ считаю себя экспертом по приготовлению и дегустации хмеля, правда, рецептам Чуня отдаю особое предпочтение... В конце концов у него был лучший учитель.\n\n<Гао Летний Ветерок с довольным видом подмигивает вам.>', '', 64978),
(294617, 'ruRU', 'Приветствую, друг. Чем я могу тебе помочь в этот прекрасный день?\n\nЕсли нужен совет по обустройству жилья, должен сразу предупредить: я очень давно не занимался подобным на профессиональном уровне. На закате лет я больше предпочитаю оценивать дизайн интерьера, а не практиковать его.\n\nКстати, я бы с удовольствием посмотрел, что ты сделаешь со своим жильем.', '', 64978),
(294576, 'ruRU', '', 'Я жду.', 64978),
(294542, 'ruRU', '', 'Любопытно. Должно быть, он из соседней временной линии.\n\nВ этом свитке скрыто огромное количество темпоральной энергии. Советую сжечь его в нашем костре.\n\nПрежде чем бросить его в огонь, можешь что-нибудь на нем написать. Энергии в нем столько, что это сообщение наверняка долетит до твоих товарищей, других путешественников во времени.\n\nНо подбирай  слова тщательно. Если только не нарушатся физические законы самого времени, то подобную редкость, скорее всего, можно будет найти только раз в неделю.', 64978),
(294536, 'ruRU', '<Уютное местечко, где можно приготовить еду.>', '', 64978),
(294513, 'ruRU', '', 'Надо было догадаться, что не обошлось без тебя.\n\nЧто тебе нужно? Или ты хочешь извиниться за этот беспорядок?', 64978),
(294466, 'ruRU', '<Прежде чем бросить в огонь незаполненный буклет вестника рока, вы решаете написать на нем сообщение. Что вы напишете?>', '', 64978),
(294417, 'ruRU', 'Ясно.', '', 64978),
(294415, 'ruRU', 'Хм... Эрий никогда не думал о том, чтобы превращать в утиль еду.\n\nЗначит ли это, что Эрий мог бы питаться утилем?\n\nНет, это было бы не умно.\n\nЕда – для поедания, а утиль – для утилизирования. Никаких исключений.\n\nТаков путь.', '', 64978),
(294414, 'ruRU', 'О да. Эрий прекрасно знает, о чем говорит $p.\n\nКогда Эрий спит, иногда его сны наполнены бронзой, песком и разбиванием вещей.\n\nИ когда Эрий просыпается, он испытывает огромное желание превратить что-нибудь в утиль.\n\nЭто замкнутый  круг.', '', 64978),
(294411, 'ruRU', 'Когда я сейчас увидел себя, то испугался, что дело именно в этом.\n\nМы с Горосом  часто говорили о том, как нас страшит этот момент. Но он настал, и оказалось, что меня переполняет радость. Ужас куда-то испарился.\n\nЛюбопытно.\n\nЯ получил немало пользы, изучая эту временную линию вместе с тобой, $p.\n\nПрощай. Счастливого тебе пути.', '', 64978),
(294403, 'ruRU', '', 'Лучше не спешить. Ведь вернуться в эту временную линию не удастся.\n\nЕсли забудешь ключи, например, возникнет серьезная проблема.', 64978),
(294402, 'ruRU', '', 'Мудрое решение. Подобный способ покидать мероприятия создает определенную ауру таинственности и изысканности.', 64978),
(294401, 'ruRU', '', 'Это хорошо. Мне нужны разговорчивые собеседники.\n\n<Сакердорму со вздохом оглядывается на Пифагора.>', 64978),
(294397, 'ruRU', '', 'Это было бы благоразумно, особенно если учесть другой вариант.\n\n<Сакердорму бросает взгляд на временной вихрь.>\n\nСкажи, ты останешься до конца или сбежишь до того, как все пойдет вразнос?', 64978),
(294384, 'ruRU', 'Ой! Ну ладно.\n\nПрощай, $r.', '', 64978),
(294379, 'ruRU', '', 'Ха-ха, очень смешно, $p.\n\nПохоже, я уже с ума схожу от беспокойства. Но кто меня в этом упрекнет?\n\n<Она указывает на временной вихрь в небе.>\n\nСпасибо тебе за эти прощальные слова. Не знаю, где и когда ты окажешься, но желаю тебе удачи.', 64978),
(294378, 'ruRU', '', 'О нет! Я так и знала!\n\n<Секунду спустя до Линдорми доходит ваш сарказм, и она переводит взгляд на воронку в небе.>\n\nА, ясно.\n\nТут столько всего происходит, вот я и нервничаю.\n\nСпасибо, $p. Не знаю, где ты теперь окажешься, но все равно – береги себя.', 64978),
(294377, 'ruRU', '', 'О, тогда я спокойна.\n\nНу, насколько это возможно в данных условиях.\n\n<Она указывает на временной вихрь в небе.>\n\nБереги себя, $p. Надеюсь, твоя следующая временная линия не будет похожа на эту – темную и искаженную. Это было бы ужасно.', 64978),
(294373, 'ruRU', '', 'Ой! Ты же уходишь не из-за того, что разбилась временная линия?\n\nЯ что-то не так сказала?\n\nЧто-то не то сделала?\n\nЯ что-то сказала или сделала в разбитой временной линии Вечнос?', 64978),
(294371, 'ruRU', '', 'Ты вроде как ничего.\n\nНадо как-нибудь с тобой потусить.', 64978),
(294370, 'ruRU', '', 'Круто.\n\nИ как это?\n\nА, точно. Мне безразлично.', 64978),
(294369, 'ruRU', '', 'А, точно.\n\nКруто.\n\nЕще увидимся.\n\nНу, или не увидимся.', 64978),
(294365, 'ruRU', '', 'Круто. Но ладно.\n\nТы вообще кто?', 64978),
(294360, 'ruRU', '', 'О, золотко, не стоит благодарности. С тобой  же так легко работать.\n\nНу что, успеем навести тебе красоту еще раз?', 64978),
(294358, 'ruRU', '<Когда вы обнимаете бронедона, искра понимания и вопли немедленно сменяются новыми ведрами слюны и радостным хрюканьем. Возможно, счастье действительно в неведении.>', '', 64978),
(294356, 'ruRU', '<Новые потоки слюны. Бронедон тяжело дышит и хрюкает. Вдруг в его небесно-голубых глазах мелькает искра понимания, и он издает душераздирающий вопль.>', '', 64978),
(294354, 'ruRU', '<Бронедон пускает слюни и хрюкает, изо всех сил показывая, что он самый лучший-прелучший бронедон на свете.>', '', 64978),
(294352, 'ruRU', '<Узнав вас, бесконечный бронедон взволнованно рычит и сопит.>', '', 64978),
(294350, 'ruRU', 'Боюсь, что нет. Но проверь, вдруг тебе приглянется то, что я продаю.', '', 64978),
(294349, 'ruRU', 'Как насчет подарка на прощание?', '', 64978),
(294348, 'ruRU', 'Береги себя, $p. Возможно, в будущем наши нити снова сплетутся.', '', 64978),
(294344, 'ruRU', 'О, $p. У меня в коллекции столько всего, но самое ценное – это, наверное, твоя дружба.', '', 64978),
(294338, 'ruRU', '<Поставщик в капюшоне, похоже, сбит с толку.>\n\nТы угрожаешь мне, что ли?', '', 64978),
(294335, 'ruRU', '', 'Ткач Араз пожертвовал собой и перегрузил манагорн своей энергией. Глупец был готов пойти на все. Теперь возвращение Пространствуса ничто не остановит.\n\nВыйдите в пустоши и найдите другой путь к Сердцу манагорна. Мы же со Странником попробуем стабилизировать его, чтобы Пространствус не возродился раньше времени.', 64978),
(294317, 'ruRU', '$p.\n\nКак говорил мой пра-пра-пра-дедушка, его пра-пра-пра-дедушка всегда говорил, что его пра-пра-пра-дедушка всегда говорил, что ЕГО дедушка отлично умел прощаться.\n\nА вот я – не умею.\n\nКогда свидимся, тогда и свидимся.', '', 64978),
(294316, 'ruRU', 'Ой! Ну в таком случае, попрощаемся и спляшем так, словно завтра конец света.', '', 64978),
(294314, 'ruRU', 'Чушь. Небо практически не начало падать на землю.', '', 64978),
(294310, 'ruRU', 'Мне было так приятно с тобой общаться, $p.\n\nНе знаю, где ты окажешься, когда все это исчезнет, но если тебе понадобятся новые тряпки, просто спроси Фредди.\n\nВсе знают Фредди Ниткса, а если не они, то их знакомые, или знакомые знакомых.', '', 64978),
(294305, 'ruRU', 'В твоих словах скрыта мудрость, $p.\n\nОружие и щит дополняют друг друга, но они ничто, пока не окажутся в руках воина. Поэтому и братья по оружию должны поддерживать друг друга и действовать, словно единое целое.\n\nВременному потоку, в котором ты окажешься, повезло: у него будет достойный воитель.', '', 64978),
(294304, 'ruRU', 'Твои слова воодушевляют.\n\nНо если ты выбираешь подобную тактику, время становится твоим противником. Терпение твоего врага может оказаться сильнее, чем твой натиск.\n\nМне будет не хватать наших с тобой бесед, $p. \n\nВременному потоку, в котором ты окажешься, повезло: у него будет достойный воитель.', '', 64978),
(294303, 'ruRU', 'Все так.\n\nНо следует помнить, что идеальной защиты не существует. Если враг нашел слабое место в твоей защите, нужно проявить терпение и найти противоядие.\n\nВременному потоку, в котором ты окажешься, повезло: у него будет достойный воитель.\n\nПрощай, $p.', '', 64978),
(294291, 'ruRU', 'Здравствуй, $p.\n\nСкажи, что позволило тебе одержать столько побед?', '', 64978),
(294287, 'ruRU', 'Прощай, друг мой. Не знаю, в каком будущем ты окажешься, но пусть твоя охота будет удачной.', '', 64978),
(294285, 'ruRU', 'Это точно не моя шерсть...', 'Это точно не моя шерсть...', 64978),
(294283, 'ruRU', 'Я Сисаи, брат Ли Ли. Жаль, мне не удалось лично тебя поприветствовать. Получается, все ждут только нас с тобой?\n\nНесколько дней назад я начал готовиться к фестивалю в деревне У-Сун, но вдруг понял, что наши лучшие фейерверки куда-то запропастились! Я вернулся за ними домой, но так и не смог их отыскать. Времени почти не осталось, так что, боюсь, нам придется обойтись тем, что есть.\n\n<Сисаи лапой вытирает пот со лба.>\n\nЗдорово, что мы наконец-то встретились, друг Ли Ли. Я и ее саму уже много лет не видел. Представляю, сколько у нас накопилось историй... Правда, у нее их будет больше, чем у меня. Я, кстати, теперь живу в деревне Утреннего Бриза. Здесь очень красиво, особенно у реки.', '', 64978),
(294263, 'ruRU', '', '<Агос кивает, давая понять, что услышала вас, и закрывает глаза в знак искренности.>', 64978),
(294254, 'ruRU', 'Мы с Гневионом полетим вперед и осмотрим остров.', '', 64978),
(294252, 'ruRU', 'Ваша задача – отыскать пропавшую экспедицию и помочь ей добраться до Драконьих островов.', '', 64978),
(294251, 'ruRU', 'Вы вызвались участвовать в спасательной операции, которую возглавили драконы Гневион и Калесгос.', '', 64978),
(294246, 'ruRU', '', 'Благослови небо твою душу. Я с самого начала знала, что ты мне понравишься. Я – отличный рассказчик, я – душа любой компании, и, наверное, многие мне завидуют.', 64978),
(294245, 'ruRU', '', 'Ну, тогда я не понимаю, чем все недовольны. Спасибо, твои словам меня успокоили.', 64978),
(294244, 'ruRU', '', 'Ну, спасибо за откровенность. Пожалуй, иногда я действительно бываю слегка навязчивой.', 64978),
(294240, 'ruRU', '', 'Это очень мило с твоей стороны, $p. Но пока ты еще здесь, я просто должна задать тебе этот вопрос. Все говорят, что я слишком много болтаю?', 64978),
(294095, 'ruRU', 'Вижу, мое письмо тебя нашло, $p. Рад, что ты здесь! А вот Ли Ли что-то не уверена во сей этой затее.\n\nЕе можно понять. Дом – это, конечно, здорово, но возвращаться туда бывает странно, особенно после долгой отлучки.\n\nАиса будет ждать нас на месте. Что скажешь, можем отправляться?', '', 64978),
(294046, 'ruRU', 'Да, воистину! Эрий  думает точно так же.\n\nНо не забывай, $p, работа с утилем приятна сама по себе, даже без бронзы и бесконечной силы.\n\nКогда Эрию хочется отдохнуть, он получает огромное наслаждение, занимаясь скрапбукингом.', '', 64978),
(294045, 'ruRU', 'Эрий рад тому, что может повидаться с тобой напоследок, $p.\n\nНо прежде чем Эрий попрощается, он должен задать тебе, $p, один вопрос. Среди всех вещей, разбитых тобой на Расколотых островах, какая была лучшей?', '', 64978),
(294044, 'ruRU', 'Спасибо, $p.\n\nВсе говорят, что с возрастом становится легче прощаться, но лично мне кажется, что прощание не должно быть легким, ведь в этом весь смысл.', '', 64978),
(294030, 'ruRU', 'Ух ты! Вот это буря, а?\n\nБыло бы безответственно с твоей стороны бросить меня в одиночестве в такую жуткую бурю.\n\nТебе точно нужно остаться. У меня есть еда, есть одеяла, под которыми можно прятаться, пока буря не пройдет. Будем сидеть допоздна и рассказывать истории о твоих приключениях!', '', 64978),
(293945, 'ruRU', '', '<Моратари закатывает глаза.>\n\nКак скромно с твоей стороны. В любом случае это тоже информация!', 64978),
(293939, 'ruRU', '', 'Азерот навсегда изменился, $p. Меч Саргераса не уничтожил наш мир только благодаря подвигам и самопожертвованию героев вроде тебя. Скажи мне, что ты чувствуешь теперь, когда твой потенциал раскрылся полностью?', 64978),
(293938, 'ruRU', '', 'Я поняла твою точку зрения. Пожалуй, ответов на этот вопрос существует не меньше, чем бойцов в Армии погибели Легиона.\n\nОднако именно твое мнение наиболее ценно для меня, $p. Я снабжу эти данные примечанием, чтобы на досуге как следует над ними поразмыслить.', 64978),
(293932, 'ruRU', '', 'Как была сформирована Армия погибели Легиона? Можем ли мы вынести из ее создания какой-либо урок?', 64978),
(293925, 'ruRU', '', 'Тонко подмечено. Над этим стоит поразмыслить. Спасибо тебе за твое мнение, $p.', 64978),
(293918, 'ruRU', '', 'Скажи мне, $p, что сталось с Сурамаром и повстанцами? Какие уроки мы можем извлечь из этой истории?', 64978),
(293304, 'ruRU', 'Сдается мне, нам надо идти на этот звук...', '', 64978),
(293255, 'ruRU', '', 'Вот клетка, как и обещано. Я даже приложу к ней метку переноса в подарок.', 64978),
(293253, 'ruRU', '', 'Надеюсь, Аллерия ни о чем не пожалела.', 64978),
(293250, 'ruRU', '', 'Уверена, вам с Аллерией не терпится получить клетку.\n\nА я хочу поскорее получить то, что нужно мне.', 64978),
(293249, 'ruRU', '', '$n, как прекрасно, что ты здесь. Какими судьбами?', 64978),
(293243, 'ruRU', '', 'Чем я могу тебе помочь?', 64978),
(293235, 'ruRU', '<Панель управления отключена. Ее уже использовали для того, чтобы направить наверх мощный поток, поразивший силы противника.>', '<Панель управления отключена. Ее уже использовали для того, чтобы направить наверх мощный поток, поразивший силы противника.>', 64978),
(293200, 'ruRU', 'Если кто и знает, где ее искать, так это Умбрий.', '', 64978),
(293199, 'ruRU', 'Что бы мы без тебя делали... Ладно, идем.', '', 64978),
(293153, 'ruRU', 'Изера – предыдущий Аспект зеленых драконов и моя бабушка.\n\nОна подверглась порче и была убита в ходе последнего нашествия Легиона.\n\nНо Изера продолжает существовать в Арденвельде – части царства мертвых под названием Темные Земли.\n\nБабушка была свидетельницей многих событий. Я могу показать тебе, что с ней произошло.', '', 64978),
(293079, 'ruRU', '', 'Готова доложить о передвижениях Воплощений... и выступающих против нас драктиров.', 64978),
(292407, 'ruRU', '<Портал Калесгоса мерцает перед вашим взором.>', '', 64978),
(292177, 'ruRU', 'Шу! Угоу! Что с вами случилось?', '', 64978),
(292132, 'ruRU', '', 'Конечно, я выгляжу иначе. Я выросла! Не могла же я вечно оставаться ребенком! Так не бывает.', 64978),
(292131, 'ruRU', '', 'Я буду тебе писать!', 64978),
(292130, 'ruRU', '', 'До новых приключений!', 64978),
(292129, 'ruRU', '', 'Возвращайся, поболтаем!', 64978),
(292128, 'ruRU', '', 'До встречи!', 64978),
(292127, 'ruRU', '', 'Как хорошо, что ты здесь!', 64978),
(292126, 'ruRU', '', 'Мир полон чудес!', 64978),
(292125, 'ruRU', '', 'Как поживаешь?', 64978),
(292124, 'ruRU', '', 'Столько лет прошло!', 64978),
(292123, 'ruRU', 'Смотри не поранься.', '', 64978),
(292122, 'ruRU', 'Сила бывает самая разная.', '', 64978),
(292121, 'ruRU', 'Я буду здесь.', '', 64978),
(292120, 'ruRU', 'Йо-Йо всегда поможет.', '', 64978),
(292119, 'ruRU', 'Тебя подбросить?', '', 64978),
(292118, 'ruRU', 'А вот и ты.', '', 64978),
(292117, 'ruRU', '', 'О... уже уходишь?', 64978),
(292116, 'ruRU', '', 'Пока-пока!', 64978),
(292115, 'ruRU', '', 'Поиграем?', 64978),
(292114, 'ruRU', '', 'Эй! Я Цзя!', 64978),
(292113, 'ruRU', 'Мы будем скучать.', '', 64978),
(292112, 'ruRU', 'Возвращайся поскорей.', '', 64978),
(292111, 'ruRU', 'Что, снова в путь?', '', 64978),
(292110, 'ruRU', 'Оставайся сколько пожелаешь!', '', 64978),
(292109, 'ruRU', 'С возвращением!', '', 64978),
(292108, 'ruRU', 'Добро пожаловать!', '', 64978),
(292107, 'ruRU', 'Заходи почаще!', '', 64978),
(292106, 'ruRU', 'Я тебя запомню.', '', 64978),
(292105, 'ruRU', 'Еще увидимся!', '', 64978),
(292104, 'ruRU', 'Рад встрече!', '', 64978),
(292103, 'ruRU', 'Есть что рассказать?', '', 64978),
(292102, 'ruRU', 'Чем могу тебе помочь?', '', 64978),
(291696, 'ruRU', '', 'Калесгос, возьмешь новобранца на Драконьи острова? Мне нужно вернуться в Штормград.', 64978),
(291617, 'ruRU', 'Я тут слыхал, Саргерас вонзил в землю огромный меч, и он до сих пор там и торчит. Как думаешь, стоит мне вытащить его и забрать себе?', '', 64978),
(291608, 'ruRU', 'О, $p, ты очень вовремя. Я тут дремал и как раз только проснулся.\n\nХотел спросить твоего совета – как ты думаешь, где на Расколотых островах самое подходящее место, чтобы вздремнуть? Что тебе больше по душе из этих вариантов?', '', 64978),
(291557, 'ruRU', '', 'Слушай, а ты же ведь знаешь Иллидана Ярость Бури? Можешь меня с ним познакомить?', 64978),
(291553, 'ruRU', '', '$p, нужна твоя помощь.\n\nМеня вдохновляют образы многих знаменитостей с Расколотых островов, но я могу выбрать только один. Поможешь сделать выбор? Вот мой список.\n\n<Лара протягивает вам список имен, большинство из которых уже вычеркнуто. Осталось только три.>', 64978),
(291545, 'ruRU', '$p, чисто из... кхм... исследовательских соображений интересуюсь – где, по-твоему, можно найти больше всего экзотических предметов для... кхм... изучения?', '', 64978),
(291537, 'ruRU', 'Скажи, $n, какое самое могучее создание тебе встретилось в твоих странствиях? Хочу поохотиться на него в следующей временной линии.', '', 64978),
(291529, 'ruRU', 'Скажи, какой величайший эпизод чистого разрушения тебе довелось увидеть своими глазами во время твоего путешествия по Расколотым островам?', '', 64978),
(291510, 'ruRU', '', 'Поэтому сегодня мы не только прощаемся с прошлым, но и приветствуем будущее. Всего хорошего и до новых встреч.', 64978),
(291509, 'ruRU', '', 'И хотя мы покинем эту реальность и вернемся в свое время, обретенные здесь знания останутся с нами навсегда.', 64978),
(291508, 'ruRU', '', 'Мы не ошиблись, взяв тебя с собой. Твои подвиги открыли для нас больше нового, чем это могли бы сделать тысячи книг.', 64978),
(291507, 'ruRU', '', 'Как я и обещала Ноздорму, мы покинем эту временную линию. Наш эксперимент подошел к концу.', 64978),
(291497, 'ruRU', '', 'Как бы они себя ни называли, от меня им не скрыться.', 64978),
(291482, 'ruRU', '', 'Если Ксал\'атат думает, что ей удалось скрыть свою новую армию, она сильно ошибается.\n\nЯ отыщу ее Пожирающий сонм и узнаю его слабые места.', 64978),
(291425, 'ruRU', 'Возможно, мы встретимся в какой-нибудь версии будущего. Так что я могу смотреть вперед с надеждой.', '', 64978),
(291424, 'ruRU', 'Время познается в перспективе. С моей точки зрения, будущее простирается очень далеко.', '', 64978),
(291423, 'ruRU', 'Многие считают, что драконы Бесконечности не думают о будущем, а лишь оглядываются на прошлое. Это не так.', '', 64978),
(291422, 'ruRU', 'Мы почти закончили. Подобно затухающему огню горна, мы исчезнем из этого времени, будто никогда здесь не были.', '', 64978),
(291416, 'ruRU', '', 'Что ж, если я когда-нибудь этим займусь, то с радостью приму твою помощь. Тогда и это прощание перерастет в новое приветствие.', 64978),
(291415, 'ruRU', '', 'И все же они так сильно отличаются друг от друга... Интересно, почему... Быть может, их тоже стоит хорошенько изучить.', 64978),
(291414, 'ruRU', '', 'Когда постоянно путешествуешь во времени, приветствия начинают сливаться с прощаниями. Порой их бывает трудно различить.', 64978),
(291413, 'ruRU', '', 'Должна сказать, эксперимент удался на славу. А теперь в песочных часах осыпаются последние крупицы. Пески времени ждут нового поворота.', 64978),
(291395, 'ruRU', 'Кстати, мне нужно узнать  твою точку зрения. Ну что, поделишься мудростью с собратом-кузнецом?', '', 64978),
(291389, 'ruRU', '', '<Внезапно Моратари переводит взгляд на свой планшет и откашливается.>\n\nКстати о данных... Что тебе удалось узнать о влиянии артефактов на эту временную линию? Может, поделишься своими знаниями?', 64978),
(291293, 'ruRU', 'Интересные обстоятельства для знакомства, ничего не скажешь! Я Калесгос, Аспект синих драконов.\n\nСпасибо за помощь с этим гнусным ритуалом. Я почти уверен, что ограм помогала еще какая-то сила.\n\nДавай-ка покинем это место. Тебя ждут приключения на Драконьих островах.', '', 64978),
(291273, 'ruRU', '', 'Посмотрим, что будет с током времени, если мы сделаем его нашей переменной.', 64978),
(291272, 'ruRU', '', 'Когда времени достаточно, возможно все. А вот когда его нет, тогда...', 64978),
(291271, 'ruRU', '', 'Интересно, как будут развиваться исторические события, если их сжать или растянуть?', 64978),
(291270, 'ruRU', '', 'В истории все идет по своему расписанию.', 64978),
(291080, 'ruRU', 'Мне надо лететь в Лазурный Простор, но мы наверняка еще встретимся. Удачных тебе приключений!', '', 64978),
(291077, 'ruRU', 'Как можно отказаться после такого спасения? Скажи, когда сможешь отправляться. Объясню все по пути.', '', 64978),
(291076, 'ruRU', 'Калесгос! Возьмешь новобранца на Драконьи острова? Мне надо в Оргриммар – рассказать о том, что здесь случилось.', '', 64978),
(291074, 'ruRU', 'Я свободен! А теперь уберемся из этого места!', '', 64978),
(291073, 'ruRU', 'Я... себя не контролирую! Продержитесь, пока я... не развею чары!', '', 64978),
(291054, 'ruRU', '', 'Вперед! Надо остановить ритуал, пока еще не слишком поздно.', 64978),
(291050, 'ruRU', 'Нельзя останавливаться. Помешаем ограм и сорвем их мерзкий ритуал.', '', 64978),
(291047, 'ruRU', '', 'Хорошо. На раздумья нет времени. Надо успеть спасти и Гневиона, и Калесгоса.', 64978),
(291046, 'ruRU', '', 'Нужно снять с Гневиона сдерживающие чары. Моя магия поможет избавиться от нежити.', 64978);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(291045, 'ruRU', '', 'Постой-ка. Я вижу... Гневиона?', 64978),
(291044, 'ruRU', '', 'Если у него есть камера, зачем мы отправили наверх новобранца?', 64978),
(291043, 'ruRU', '', 'Как хорошо, что ты в порядке. Но куда пропали остальные участники экспедиции?', 64978),
(291042, 'ruRU', '', 'Отправляйся к капитану Гэррик. А я обойду остров и поищу других выживших.', 64978),
(291041, 'ruRU', '', 'Верни наши припасы, но знай: мурлоков нельзя недооценивать. Особенно когда их много.', 64978),
(291040, 'ruRU', '', 'Тебе повезло! Море тебя пощадило.', 64978),
(291039, 'ruRU', '', 'Дальше позанимайся с Коулом. Сдается мне, это не простой дождь.', 64978),
(291038, 'ruRU', '', 'Отлично! А теперь... Стой... Почему пошел дождь? На небе не было ни облачка...', 64978),
(291036, 'ruRU', '', 'Тебе хорошо бы повторить основы. Кто знает, что ждет нас на берегу.', 64978),
(291035, 'ruRU', '', 'Остров совсем рядом. Так что давай потренируемся.', 64978),
(291017, 'ruRU', '', '[CUT, DO NOT RECORD] We cannot allow Kalecgos to suffer this grim fate! For the Alliance!', 64978),
(291016, 'ruRU', '', '[CUT, DO NOT RECORD] Then we must make haste. We\'ll rescue the rest of the expedition and launch an assault on the citadel.', 64978),
(291015, 'ruRU', '[CUT, DO NOT RECORD] These ogres will face the fury of the Horde. Lok-tar ogar!', '', 64978),
(291014, 'ruRU', '[CUT, DO NOT RECORD] Then there\'s no time to waste. We\'ll rescue the rest of the expedition and lay siege to the citadel.', '', 64978),
(291013, 'ruRU', '[CUT, DO NOT RECORD] And there it is. If they complete that ritual, Kalecgos will be theirs to command!', '', 64978),
(291012, 'ruRU', '[CUT, DO NOT RECORD] From what I overheard, they are performing a ritual that will place him fully under their control.', '', 64978),
(291011, 'ruRU', '[CUT, DO NOT RECORD] Those ogres used some form of ancient shadow magic to capture us. They took Kalecgos elsewhere.', '', 64978),
(290995, 'ruRU', 'Как это все унизительно...', '', 64978),
(290971, 'ruRU', 'Его имя Калесгос, ты, ничтожество! Отпусти меня, а не то пожалеешь!', '', 64978),
(290970, 'ruRU', 'Жалкий драконишка! Мы заберем твою душу и подчиним себе синего!', '', 64978),
(290969, 'ruRU', 'Давай, лишь бы сработало. Надо поскорее освободить Гневиона!', '', 64978),
(290968, 'ruRU', 'Они вытягивают из Гневиона душу. Надо придумать, как прорваться через эту нежить!', '', 64978),
(290967, 'ruRU', 'Стой! Я кого-то вижу... Это... Гневион?', '', 64978),
(290966, 'ruRU', 'Зачем отправлять новобранца, если там и так есть камера?', '', 64978),
(290965, 'ruRU', 'Рад, что с тобой все хорошо. Но где остальные участники экспедиции?', '', 64978),
(290964, 'ruRU', 'Верни наши припасы, но берегись мурлоков. Они опасны в стаях.', '', 64978),
(290963, 'ruRU', 'Хвала стихиям, ты в порядке!', '', 64978),
(290961, 'ruRU', 'Дальше потренируйся с Трогом. Не нравится мне эта перемена погоды...', '', 64978),
(290960, 'ruRU', 'Неплохо. А теперь... Что, дождь? Но небо только что было ясное...', '', 64978),
(290957, 'ruRU', 'Всегда будь в боевой готовности. Кто знает, что поджидает нас на суше.', '', 64978),
(290956, 'ruRU', 'Остров совсем рядом. Давай потренируемся.', '', 64978),
(290954, 'ruRU', 'Стало известно, что экспедиция на Драконьи острова потерпела крушение и оказалась на необитаемом острове.', '', 64978),
(290799, 'ruRU', '', 'Что ж... Надеюсь, однажды она сделает это лично. Идем, Аратор. Кель\'Талас ждет.', 64978),
(290798, 'ruRU', 'Ты исполнила ее желание. Она хотела тебя за это поблагодарить.', '', 64978),
(290797, 'ruRU', '', 'Этого Аллерия и хотела. Подарить тебе счастливое детство, которого у нас не было.', 64978),
(290796, 'ruRU', 'Даже не представляю, через что они прошли. По сравнению с ними... я жил тихо и безмятежно.', '', 64978),
(290795, 'ruRU', 'Возможно, я никогда не пойму, почему мать и Сильвана избрали такой одинокий путь. Но я уважаю их выбор.', '', 64978),
(290794, 'ruRU', '', 'Значит, ты видел их обеих... Жаль, что они тебя не послушали.', 64978),
(290793, 'ruRU', '', 'Береги себя, Аратор. Защищай Луносвет с честью. Как все Ветрокрылые.', 64978),
(290792, 'ruRU', 'Я... передам ей, что ты сказала.', '', 64978),
(290791, 'ruRU', '', 'Надо ее поблагодарить.', 64978),
(290790, 'ruRU', '', 'Ты... всегда видишь в других хорошее, Аратор. Сразу видно, что тебя растила Вериса.', 64978),
(290789, 'ruRU', 'И не признаете иного пути, кроме своего. Вы не такие разные, как тебе кажется.', '', 64978),
(290788, 'ruRU', 'Она, как и ты, жертвует всем ради долга. Вы обе не жалеете себя ради тех, кого хотите защитить...', '', 64978),
(290787, 'ruRU', 'Но, мама, повстречав ее сегодня... я увидел твою сестру, отражение тебя.', '', 64978),
(290786, 'ruRU', 'Что собьешься с пути, ведомая темной силой, что потеряешь душу... и саму себя.', '', 64978),
(290785, 'ruRU', 'Прости. Я не хотел... Я знаю, долгое время ты боялась, что станешь такой, как она.', '', 64978),
(290784, 'ruRU', '', 'Прости, что?', 64978),
(290783, 'ruRU', 'А вы с ней в чем-то похожи.', '', 64978),
(290782, 'ruRU', '', 'Конечно, отказалась. Сильвана...', 64978),
(290781, 'ruRU', 'Она отказалась. Как ты и предупреждала.', '', 64978),
(290780, 'ruRU', '', 'Значит, ты говорил с ней?', 64978),
(290779, 'ruRU', '', 'Возвращайся на Азерот. Приготовься к грядущей битве. Однажды наши пути пересекутся вновь.', 64978),
(290778, 'ruRU', '', 'Но знай: я не могу остановиться сейчас. Я не должна останавливаться, иначе все, что я сделала, будет напрасно.', 64978),
(290777, 'ruRU', '', 'Я не жалею о том, что совершила, но и не осуждаю тех, кто обнажил против меня клинки.', 64978),
(290776, 'ruRU', '', 'Я нажила немало врагов, следуя своему пути. Многие когда-то были союзниками.', 64978),
(290775, 'ruRU', '', 'Передай, что Темная Госпожа все видит даже сейчас.', 64978),
(290774, 'ruRU', '', 'Возвращайся на Азерот, мой воин. В грядущие дни ты будешь там нужнее. И если кто-то из союзников спросит...', 64978),
(290773, 'ruRU', '', 'Знай вот что. Я не оглядываюсь назад. После всего, что случилось, всего, что мы совершили... остановиться сейчас было бы преступлением.', 64978),
(290772, 'ruRU', '', 'Когда-то ты и другие верные воины следовали за мной, куда бы я ни повела.', 64978),
(290771, 'ruRU', '', 'Я лучше других познала природу смерти. А здесь... все слишком просто. Слишком закономерно.', 64978),
(290770, 'ruRU', '', 'Ты все понимаешь, верно? Утроба. Темные Земли. Все это не давало мне покоя после смерти Тюремщика.', 64978),
(290769, 'ruRU', '', 'Но, как я уже сказала, сейчас для меня не время возвращаться в мир живых.', 64978),
(290768, 'ruRU', '', 'Но в одном Аратор прав. Я Ветрокрылая. И я не забыла о своих корнях.', 64978),
(290767, 'ruRU', '', 'Спасибо, что сдерживаешь энтузиазм моего племянника. Он силен, но часто лезет на рожон. У нас это семейное.', 64978),
(290766, 'ruRU', 'Сильвана... Хорошо. Кажется, я понимаю.', '', 64978),
(290765, 'ruRU', '', 'Говоришь, Кель\'Таласу нужны Ветрокрылые? Так иди, Аратор. Будь Ветрокрылым.', 64978),
(290764, 'ruRU', '', 'Но я отреклась от них, когда спустилась в Утробу. Мое место... и долг... только здесь. Не среди живых.', 64978),
(290763, 'ruRU', '', 'У меня самой было немало званий. Командир следопытов. Темная Госпожа. Королева-банши. Даже вождь.', 64978),
(290762, 'ruRU', '', 'Товарищи-паладины зовут тебя \"Искупитель\", но я не ищу искупления.', 64978),
(290761, 'ruRU', 'Я видел, как ты помогаешь заточенным здесь душам. Я за тебя поручусь. Помогу убедить их...', '', 64978),
(290759, 'ruRU', 'Ты творила ужасные вещи. Я этого не отрицаю. Но чего стоит искупление, если оно тоже приносит вред?', '', 64978),
(290758, 'ruRU', '', 'А народ Тельдрассила? Что подумают они, если я вернусь?', 64978),
(290757, 'ruRU', 'Сильвана... Азерот в опасности. Народу Кель\'Таласа нужны сестры Ветрокрылые. Им нужна ты.', '', 64978),
(290756, 'ruRU', '', 'Довольно. Хотел поговорить? Говори. Зачем ты пришел?', 64978),
(290755, 'ruRU', 'Сильвана... это было...', '', 64978),
(290754, 'ruRU', '', 'Увязался за мной. Преследует молча, исчезает, а потом возвращается вновь.', 64978),
(290753, 'ruRU', 'Еще один дух?', '', 64978),
(290752, 'ruRU', '', 'Надеюсь, твоя богиня ждет тебя в своем царстве.', 64978),
(290751, 'ruRU', '', 'Мать-Луна... я тебя слышу. Прошу, избавь меня от этих мук...', 64978),
(290750, 'ruRU', '', 'Спасайте детей! Тельдрассил горит!', 64978),
(290749, 'ruRU', '', 'Что ж, как пожелаешь. Идем, Аратор. У нас еще много дел.', 64978),
(290748, 'ruRU', 'Лучше уж вечные муки, чем принять от тебя спасение.', '', 64978),
(290747, 'ruRU', 'Ты приказала меня казнить. Исказила разум Дэрека.', '', 64978),
(290746, 'ruRU', 'Что, Королева-банши, пришла завершить начатое?', '', 64978),
(290745, 'ruRU', '', 'Идем. Продолжим работу.', 64978),
(290743, 'ruRU', '', 'Стой. Пускай выплеснет свой гнев.', 64978),
(290742, 'ruRU', 'Сильвана! Берегись...', '', 64978),
(290741, 'ruRU', '', 'Чудовище! Предательница! Ты обрекла нас всех!', 64978),
(290740, 'ruRU', '', 'Я лишь сказала ему нужные слова. ', 64978),
(290739, 'ruRU', 'Не думал, что ты так верна Орде.', '', 64978),
(290738, 'ruRU', 'Значит... все кончено? Хвала Матери-Земле...', '', 64978),
(290737, 'ruRU', '', 'Отдыхай, бравый воин. Орда выстояла. Она никогда не падет.', 64978),
(290736, 'ruRU', 'Вождь приведет нас к победе! За Орду!', '', 64978),
(290735, 'ruRU', '', 'И ты уже слишком долго отвлекаешь меня от этого дела. Пора за работу, племянник.', 64978),
(290734, 'ruRU', '', 'Ты не понимаешь. Я не дарю им покой. Лишь открываю для них путь вперед.', 64978),
(290733, 'ruRU', 'Ведь половина здешних душ предпочтет уничтожить тебя, а не обрести покой.', '', 64978),
(290732, 'ruRU', '', 'Разве не очевидно? Это мое наказание. А еще... и мое предназначение.', 64978),
(290731, 'ruRU', 'Почему ты это делаешь, Сильвана?', '', 64978),
(290730, 'ruRU', '', 'Знакомые, да? Ты прав. Я была за завесой истинной смерти, Аратор. Темные Земли совсем не то, чем кажутся.', 64978),
(290729, 'ruRU', 'Я думал, что Утроба будет... странной и непостижимой. Но эти постройки...', '', 64978),
(290728, 'ruRU', '', 'Если хочешь остаться, я найду, чем тебя занять.', 64978),
(290727, 'ruRU', 'Я никуда не пойду, пока мы с тобой не поговорим.', '', 64978),
(290726, 'ruRU', '', 'Тебе пора уходить, Аратор.', 64978),
(290725, 'ruRU', '', 'Не здесь. Идем.', 64978),
(290724, 'ruRU', 'Отлично. Сильвана, нам нужно...', '', 64978),
(290723, 'ruRU', '', 'Вот и все.', 64978),
(290722, 'ruRU', 'Что скажешь? Я за тобой угнался?', '', 64978),
(290721, 'ruRU', '', 'Убей эту тварь, и они лишатся подкреплений.', 64978),
(290720, 'ruRU', 'Еще не поздно признаться, что я немного боюсь высоты?', '', 64978),
(290719, 'ruRU', 'Ха... Еще чего! Для меня это... простая разминка.', '', 64978),
(290718, 'ruRU', '', 'Не можешь за мной угнаться, Аратор? ', 64978),
(290717, 'ruRU', 'И... сразу за дело. Совсем как моя мать.', '', 64978),
(290716, 'ruRU', '', 'Не стоило тебе сюда приходить. Но раз уж ты здесь, помоги отразить это вторжение.', 64978),
(290715, 'ruRU', '', 'Впрочем... Бездне здесь тоже не место. Посмотрим, чего стоят хваленые уроки Лор\'темара.', 64978),
(290714, 'ruRU', '', 'Ты возмужал, но в душе еще дитя. Здесь не место для такой сентиментальности, Аратор.', 64978),
(290713, 'ruRU', 'Теперь я силен и могу защищать наш мир. И прошу тебя о том же: вспомни долг командира следопытов.', '', 64978),
(290712, 'ruRU', 'И еще долго не мог. Лор\'темар суровый наставник, но его уроки принесли плоды.', '', 64978),
(290711, 'ruRU', '', 'Когда я видела тебя в последний раз, ты не смог бы даже поднять такой меч.', 64978),
(290710, 'ruRU', '', 'Лират? Нет... Аратор! Что ты здесь делаешь?', 64978),
(290709, 'ruRU', 'Сильвана!', '', 64978),
(290708, 'ruRU', 'Труп. И эта магия... ее ни с чем не спутать. Она где-то рядом.', '', 64978),
(290707, 'ruRU', 'Эти корзины сплели совсем недавно. Идем дальше.', '', 64978),
(290700, 'ruRU', 'Я не знаю, как Пожирающий сонм проник в Утробу и что им нужно... но эти твари не могут здесь оставаться.', '', 64978),
(290606, 'ruRU', '', 'У меня тут то, что тебе нужно.', 64978),
(290584, 'ruRU', '', 'А я сделаю то же самое в Стромгарде. Нам всем нужно отдохнуть от сражений.', 64978),
(290583, 'ruRU', 'Я вернусь в Павший Молот и помогу его восстановить.', '', 64978),
(290576, 'ruRU', '', 'Мы с Траллом разыщем их лидера. А ты разберись с врагами, затем найди нас.', 64978),
(290573, 'ruRU', '', 'В найденных тобой планах говорится, что их следующая цель – Стромгард. Нам надо спешить!', 64978),
(290571, 'ruRU', '', 'Набеги на фермы... Должно быть, огры и кобольды собирают припасы для наступления.', 64978),
(290569, 'ruRU', 'Это начинает походить на координированный удар. Идем!', '', 64978),
(290567, 'ruRU', '', 'Это нагорье и так немало пережило. Надо пресечь этот конфликт на корню.', 64978),
(290566, 'ruRU', 'Рад тебя видеть! Мы отвоюем Павший Молот.', '', 64978),
(290478, 'ruRU', 'Отличная работа сегодня. Я знаю, где еще пригодится твоя помощь.', '', 64978),
(290473, 'ruRU', '', 'Я знаю несколько мест, которым не помешает твоя помощь.', 64978),
(290097, 'ruRU', 'Рад встрече, босс. Хочешь обсудить дела? Это как раз по моей части.', '', 64978),
(290096, 'ruRU', '', 'Значит, это ты тот самый главный гоблин? Думаю, мы с тобой заработаем парочку деревянных. Что скажешь?', 64978),
(290093, 'ruRU', '', 'Ох, чуть не забыла. Мэгс хочет назначить тебе партнера по бизнесу. Но выбор будет за тобой.\n\nВ фокус-группах лучше всех показали себя Конфетка и Чип. У них великолепный стиль в одежде, они умеют очаровывать и, когда надо, драматизировать. \n\nОни идеально дополнят твой жесткий образ, и все поймут, что у тебя есть тайная мягкая сторона... как у гнилой сливы. Обычный гоблин сразу почувствует с тобой связь.\n\nНу, кого выберешь?', 64978),
(290088, 'ruRU', 'Как поживает мой топ-менеджер? Судя по тому, как ты тут распоряжаешься, скоро ты встанешь наравне с торговыми принцами, не меньше!$B$BЯ мечтаю об этом дне! Тогда я буду целыми днями торчать в качалке или загорать у бассейна.', '', 64978),
(289853, 'ruRU', 'Спасибо за спасение. Боюсь даже представить, что бы со мной сделал этот ужасный ритуал.\n\nНа Драконьих островах найдется занятие для любого искателя приключений. Мы можем поговорить об этом по пути.', '', 64978),
(289803, 'ruRU', 'Ступай к воеводе Люторез. А я продолжу искать выживших.', '', 64978),
(288646, 'ruRU', '', 'Не хочешь заняться охраной природы?', 64978),
(288645, 'ruRU', '', 'У нас есть вымирающий вид сточных кроколисков, которых надо выпустить в естественную среду обитания, и парочка \"чужеродных видов\", о которых надо бы \"позаботиться\".', 64978),
(287423, 'ruRU', 'Ты как раз вовремя, $n. Охота в самом разгаре.\n\nРыцари Бурого Стола загнали сюда зверя Глатисанта. Это ужасное, опасное чудовище. Сожрало не одного оруженосца.\n\nВеликая слава тому рыцарю, кто войдет в его логово и убьет монстра.\n\nНо Терялот уже и без того славный рыцарь, как видишь. Поэтому иди вперед, коль хочешь, и покрой славой себя.\n\nСтупай за нюхачами – они приведут тебя, куда надо.', '', 64978),
(287246, 'ruRU', 'Сдавайтесь! Подчинитесь мне! Подчинитесь Всепоглощающему!', '', 64978),
(286772, 'ruRU', '', 'Чуть-чуть боли и страданий.', 64978),
(286726, 'ruRU', '', 'Разве это натиск?', 64978),
(286715, 'ruRU', 'Это все, что ты можешь?', '', 64978),
(286535, 'ruRU', '', 'Ничтожества... У меня есть более важные дела.', 64978),
(285630, 'ruRU', 'Вид уже гораздо лучше. Ремонт удался?', '', 64978),
(285627, 'ruRU', 'Этот старый трансмогрификатор пострадал при перевозке. Попробуй починить.', '', 64978),
(285567, 'ruRU', 'Гляди в оба!', '', 64978),
(285542, 'ruRU', '', 'Ничего личного, но мне было приятно.', 64978),
(285535, 'ruRU', '', 'Где настоящая я?', 64978),
(285530, 'ruRU', '', 'Я всегда в большинстве.', 64978),
(285518, 'ruRU', '', 'И это все? Вы думаете, меня будет так легко одолеть?', 64978),
(285262, 'ruRU', 'Текущий уровень: 1\n\nЧтобы усилить подношение, убивайте боссов в Оргриммаре.', 'Текущий уровень: 1\n\nЧтобы усилить подношение, убивайте боссов в Оргриммаре.', 64978),
(285257, 'ruRU', 'Текущий уровень: 2\n\nЧтобы усилить подношение, убивайте прислужников Н\'Зота в Оргриммаре.', 'Текущий уровень: 2\n\nЧтобы усилить подношение, убивайте прислужников Н\'Зота в Оргриммаре.', 64978),
(284160, 'ruRU', 'Дальше работники справятся сами. Щит этого купола очень капризен. Ты заходи – возможно, нам снова будет нужна помощь.', '', 64978),
(284159, 'ruRU', 'Ты как раз вовремя! Споры Бездны снова просочились через наши щиты. Надо убрать их, пока они не заразили биомы.', '', 64978),
(283802, 'ruRU', 'Хочу? Скорее это необходимость!\n\nВозьми М\'арлу, и пусть съест все споры. Она их обожает.', 'Хочу? Скорее это необходимость!\n\nВозьми М\'арлу, и пусть съест все споры. Она их обожает.', 64978),
(283800, 'ruRU', 'Только поглядите, кого мне несет ласковый ветерок К\'ареша! Ты ведь тут не просто так, а из-за спор Бездны, правда? Я на днях повредил руку и не могу ехать верхом. Вот если бы ты...', 'Только поглядите, кого мне несет ласковый ветерок К\'ареша! Ты ведь тут не просто так, а из-за спор Бездны, правда? Я на днях повредила руку и не могу ехать верхом. Вот если бы ты...', 64978),
(282954, 'ruRU', '', '\"Прости за беспорядок. Мы завалены письмами и посылками буквально до потолка. Умоляю, помоги!\n\nЕсли не трудно, отнеси почту на парочку адресов, пока занимаешься своими делами на К\'ареше. Дай-ка глянуть... у меня тут в списке Покой Хосааса, уступ Зо\'Шуул, Шан\'дора и, конечно, \"\"Оазис\"\".\n\nОхо-хо! Спасибо тебе огромное, что помогаешь, $n!\"', 64978),
(282090, 'ruRU', 'Жаль, что я ее не знал.', '', 64978),
(282032, 'ruRU', '', 'Теперь мы знаем, где ждать Вешина. Осталось подготовить ловушку.', 64978),
(282003, 'ruRU', 'Я беспокоюсь за мою тетю, $n. Ее видения усиливаются. Боюсь, что это плохо на ней скажется.', '', 64978),
(281935, 'ruRU', 'Какой кошмар... Я... Ничто не могло меня к этому подготовить.', '', 64978),
(281928, 'ruRU', 'Смотри... И здесь Бездна! Но как?', '', 64978),
(281897, 'ruRU', 'О Бездне говорить непросто. Пожалуй... это некая космическая сила, которую понять невозможно. Но кое-что о ней все-таки известно. Свет и Бездна противостоят друг другу по своей природе, но при этом связаны друг с другом, да так прочно, что и представить нельзя. Они не могут существовать друг без друга.\n\nЧто еще? Ну, мы считай почти ничего о Бездне не знаем. Это источник страшной силы, но ее можно укротить и обратить себе на пользу. Аллерия Ветрокрылая, магистр Умбрий и рен\'дорай весьма наглядно это доказывают.\n\nВот только есть одно \"но\"... редко когда такая сила достается просто так. Какую же цену приходится платить эльфам Бездны? Ответ знают только они сами.', '', 64978),
(281896, 'ruRU', 'Это странное и загадочное место, о котором я знаю немногое... но расскажу все, что мне известно. Его обнаружил Дар\'Кхан Дратир, пока изучал Бездну. Сам он туда при этом попасть не смог. Лишь спустя годы до Телогруса добрался магистр Умбрий и его последователи.\n\nТелогрус оказался останками древнего мира, который давным-давно раскололо на части чудовищное создание. С тех пор осколки мира зависли на грани Бездны. Умбрий и его товарищи обосновались в Телогрусе и продолжили свои изыскания.', '', 64978),
(281895, 'ruRU', 'Дар\'Кхан Дратир... это предатель. Иначе про него и не скажешь. Он был магистром Кель\'Таласа, но потом жажда власти и себялюбие толкнули его на темный путь. Он принялся изучать запретную магию и впал в одержимость Солнечным Колодцем.\n\nКогда во время Третьей войны в Кель\'Талас пришел Артас Менетил, Дар\'Кхан принял его с распростертыми объятиями и назвал \"благословенным повелителем\". Он дал ему ключ, который позволил Артасу и Плети обойти защиту Кель\'Таласа и добраться до Солнечного Колодца. Затем Дар\'Кхан попытался предать и Артаса, но был тут же убит.\n\nВпрочем, то был не конец. Дар\'Кхан еще несколько раз обманывал смерть и возвращался в мир живых. Но в последний раз ему отрубили голову, так что, подозреваю, больше мы о нем не услышим.', '', 64978),
(281894, 'ruRU', 'Аллерия Быстрокрылая – старшая из трех печально известных сестер. Все ждали, что однажды она станет предводительницей следопытов, но Аллерия отказалась и предложила на эту роль свою сестру Сильвану. Самой же Аллерии куда больше нравилось патрулировать границы королевства и выбираться за его пределы.\n\nСо временем Аллерия и ее возлюбленный Туралион присоединились к Армии Света и вступили в бой с Пылающим Легионом. В ту пору она и повстречала Странника – таинственное создание, которое научило ее обращаться с силами Бездны.\n\nУвы, Туралион не смог принять такого. Он был предан Свету всем сердцем и душой и отвернулся от Аллерии. Но она не сдалась. Она стала грозным воином, укротила энергии Бездны и была готова защищать наш мир любой ценой.', '', 64978),
(281893, 'ruRU', 'А наару... нелегко объяснить, кто они такие. Они не из нашего мира и, боюсь, я ничего не знаю о том, откуда они взялись. Пожалуй, проще всего будет назвать их порождением Света – разумными созданиями, сотканными из священной энергии.\n\nИх самые близкие союзники – дренеи. Давным-давно, когда Саргерас связался с эредарами на Аргусе, пророку Велену было видение. Он узрел истинный план Саргераса и взмолился о помощи. На его молитвы откликнулась наару, которая обещала увести Велена и его единомышленников туда, где они будут в безопасности.\n\nТак эредары бежали со своей родины. С тех пор они зовут себя дренеями и не расстаются с наару.', '', 64978),
(281891, 'ruRU', 'Кель\'тас Солнечный Скиталец был единственным сыном короля Анастериана Солнечного Скитальца. Кроме того, он отличался исключительным талантом в магии и занял место в Совете Шестерых, который управлял Далараном. Почти все свои дни он проводил там.\n\nНо когда его отец пал в Третьей войне, Кель\'тасу пришлось возглавить свой народ. Солнечный Колодец уже нельзя было спасти от скверны, и Кель\'тасу пришлось его уничтожить. Вернувшись, Солнечный Скиталец собрал остатки своего народа и назвал их эльфами крови, чтобы почтить память павших собратьев.\n\nК несчастью, с годами он свернул на темный путь... но только потому, что хотел спасти свой народ.', '', 64978),
(281890, 'ruRU', 'Солнечный Колодец – это источник магической энергии, которая поколениями питала высших эльфов. Говорят, его сотворил Дат\'ремар Солнечный Скиталец, который украл сосуд с водой изначального Источника Вечности. Подумать только! Если даже одного сосуда хватило, чтобы создать такое... трудно представить, на что был способен сам Источник.\n\nНо Колодец был не только благом, но и проклятием. Высшие эльфы столько лет купались в его силе, что впали в зависимость.\n\nВсе, что происходило с Солнечным Колодцем, отражалось и на эльфах. И когда он исчез, народу Кель\'Таласа пришлось бороться с тяжелыми последствиями.', '', 64978),
(281889, 'ruRU', 'На самом деле Кель\'Талас был вторым поселением высокорожденных. Первым стали Тирисфальские леса, которые основатели затем покинули. Высокорожденные двинулись на север и поселились в лесистой местности, где живут и по сей день. Их предводитель Дат\'ремар Солнечный Скиталец сотворил там Солнечный Колодец – своеобразную версию Источника Вечности.\n\nТо королевство порой называют Краем Вечной Весны, потому что по воле магов там всегда стоит весна. Каждая веточка, каждое деревце и каждая речка в Кель\'Таласе прекрасны так, будто их сотворили руки умелого мастера.', '', 64978),
(281888, 'ruRU', 'Высокорожденные – это высший слой общества ночных эльфов. Тайной магией владели многие эльфы, но титул высокорожденных носили только избранники самой королевы Азшары. Чтобы попасть в их число, надо было заслужить ее милость.\n\nОни так беспечно обращались с магией, что привлекли внимание Пылающего Легиона. Началась Война Древних, которая закончилась Великим Расколом, и почти все высокорожденные отправились на морское дно со своей королевой. Лишь немногие сумели бежать и остались среди эльфов.\n\nВпрочем, со временем их все равно изгнали. Потому что, невзирая на запрет, высокорожденные так и не оставили занятия тайной магией.', '', 64978),
(281792, 'ruRU', '', 'Это касается и моих решений, и тем более действий Сильваны. Помни об этом, когда пойдешь к ней.', 64978),
(281791, 'ruRU', '', 'А может, и нет. Но то, что случилось, уже не исправить.', 64978),
(281790, 'ruRU', 'Ты не могла предвидеть, что все так обернется.', '', 64978),
(281789, 'ruRU', '', 'Но я хотела покинуть королевство. И сделала это. А когда вернулась домой...', 64978),
(281788, 'ruRU', '', 'После смерти матери командиром следопытов стала Сильвана. И мы знаем, чем это закончилось. Если бы я осталась...', 64978),
(281786, 'ruRU', '', 'Да, это возможно. В Тазавеше накоплено достаточно энергии, чтобы ненадолго открыть портал в Утробу.\n\nОднако между тем, что возможно и что действительно стоит сделать, есть огромная разница.\n\n<Ве\'нари усмехается.>\n\nНо тебе ведь все равно, что я скажу: ты в любом случае найдешь способ отправить туда Аратора. Поэтому уж лучше я помогу.', 64978),
(281784, 'ruRU', '', 'Хорошо, что я заглянула проверить, как держится моя клетка. Похоже, она даже в лучшем состоянии, чем вы.\n\nТак что вам потребовалось на этот раз?', 64978),
(281781, 'ruRU', 'Луносвету нужны сестры Ветрокрылые. Если не вернешься, мне придется разыскать Сильвану.', '', 64978),
(281775, 'ruRU', '', 'Вижу, мои ресурсы тебе хорошо послужили.', 64978),
(281759, 'ruRU', '', 'Я узнала достаточно.', 64978),
(281758, 'ruRU', 'Есть нужная информация?', '', 64978),
(281757, 'ruRU', 'Ничего не выйдет, щенок. Я сокрушу тебя!', '', 64978),
(281752, 'ruRU', '', 'Ксал\'атат больше никого у меня не отнимет!', 64978),
(281730, 'ruRU', '', 'Я читаю твои мысли. Пожирающий сонм... скрывается в Бездне...', 64978),
(281705, 'ruRU', 'Потому неудивительно, что эльфы с подозрением относились к исследованиям Дар\'Кхана... и к тем, кто хотел их продолжить.', '', 64978),
(281704, 'ruRU', 'К наступлению ночи в городе стало больше мертвых, чем живых... Потери были невообразимо ужасны.', '', 64978),
(281703, 'ruRU', 'Предательство Дар\'Кхана Дратира не просто погубило королевство. На его совести каждое убийство, совершенное Артасом и его Плетью.', '', 64978),
(281695, 'ruRU', 'Миши поможет нам добраться.', '', 64978),
(281694, 'ruRU', 'Войско Плети оставляло после себя оскверненную землю и горы трупов. Но эльфы все еще надеялись, что командир следопытов Сильвана Ветрокрылая остановит жуткого недруга.', '', 64978),
(281691, 'ruRU', 'Думаешь, ты владеешь силой Бездны лучше, чем я?!', '', 64978),
(281672, 'ruRU', '', 'Отлично, клетка у тебя. Теперь мы поймаем Вешина.', 64978),
(281633, 'ruRU', '', 'Мне не померещилось? Это правда ты?', 64978),
(281624, 'ruRU', '', 'В этом мире ничего не бывает бесплатно... в других – тоже.', 64978),
(281591, 'ruRU', 'Несомненно, это очень мрачная дорога. Но она и те воспоминания – идеальное воплощение того, кем стали эти эльфы и как им пришлось измениться.', '', 64978),
(281590, 'ruRU', 'Раз в год избранный герой син\'дорай зажигает фонари Кель\'Таласа. Каждый из них хранит в себе память о том, что никогда не должно быть забыто.', '', 64978),
(281551, 'ruRU', 'Я рад, что нашел Сильвану, но не думаю, что еще скоро рискну отправиться в загробный мир.', '', 64978),
(281433, 'ruRU', '', 'Боюсь, это случится скорее, чем ты хочешь. Но... я надеюсь, что тебе повезет.', 64978),
(281432, 'ruRU', 'Спасибо, тетя Вериса. Я вернусь, как только смогу.', '', 64978),
(281431, 'ruRU', '', 'Знаю, Аратор. Я буду ждать тебя в Дорногале. Отправимся в Луносвет, когда ты найдешь Аллерию.', 64978),
(281429, 'ruRU', '', 'Но она будет томиться в Утробе, пока не искупит свою вину.', 64978),
(281428, 'ruRU', 'Не могу сидеть и ждать, когда Ксал\'атат нанесет удар. Надо хотя бы поговорить с матерью.', '', 64978),
(281427, 'ruRU', '', 'Многие со мной не согласятся, но я верю, что Сильвана сделала бы все, чтобы защитить наш дом.', 64978),
(281397, 'ruRU', 'Похоже на видения Верисы о Луносвете. Очень надеюсь, что они не сбудутся.\n\nНо если они правдивы... Мы должны подготовить город к обороне.', '', 64978),
(281392, 'ruRU', 'Она все еще не вернулась с К\'ареша, так что нам надо ее отыскать.', '', 64978),
(281389, 'ruRU', 'Она не любит об этом говорить, но моя мать – лучший специалист по Бездне на всем Азероте.', '', 64978),
(281341, 'ruRU', 'Все в порядке. Мы ими займемся.', '', 64978),
(281274, 'ruRU', '', 'И тебя, Аратор. Идем. Думаю, тот холм на севере – самое лучшее место.', 64978),
(281273, 'ruRU', 'Он любил тебя всем сердцем.', '', 64978),
(281272, 'ruRU', '', 'Думаю, это подходящий дар. В честь дома, где мы растили детей.', 64978),
(281266, 'ruRU', '', 'Ронин подарил мне этот медальон в нашу первую годовщину.', 64978),
(281263, 'ruRU', '', 'Пока есть время, мы пришли сюда, чтобы... отдать почести. Я должна была давно это сделать.', 64978),
(281225, 'ruRU', '', 'Хорошо, что ты здесь. Твоими стараниями восстановлен Кель\'Делар, и твой визит – большая честь.\n\nМне начали являться обрывки Сияющей Песни. Эти... видения приходят и уходят, но они смутные и неясные. Все разрушается, повсюду крики и смерть.\n\nС тех пор как мы сюда прибыли, видения усилились и приносят больше боли. Но я справлюсь.\n\nИдем. Нам надо многое обсудить, а времени совсем мало.', 64978),
(281224, 'ruRU', '', 'Здравствуй, \"герой\". У меня хорошая память на лица. Никогда не забуду, что вы с Армией Покорителей творили в Даларане.\n\nМне начали являться обрывки Сияющей Песни. Эти... видения приходят и уходят, но они смутные и неясные. Все разрушается, повсюду крики и смерть.\n\nС тех пор как мы сюда прибыли, видения усилились и приносят больше боли. Но я справлюсь.\n\nВ этот раз нам придется принять твою помощь. Надо многое обсудить, а времени совсем мало.', 64978),
(281164, 'ruRU', '', 'Я должна быть здесь. Охотиться на слуг Ксал\'атат и добывать у них тайные знания.', 64978),
(281151, 'ruRU', 'Ищу тебя.', '', 64978),
(281147, 'ruRU', '<Аллерия не обращает на вас внимания. Ее пристальный взор прикован к находящемуся вдалеке лагерю Темной Стражи.\n\nВ чем дело? Почему эльфийка не реагирует на ваше присутствие?>', '<Аллерия не обращает на вас внимания. Ее пристальный взор прикован к находящемуся вдалеке лагерю Темной Стражи.\n\nВ чем дело? Почему эльфийка не реагирует на ваше присутствие?>', 64978),
(281142, 'ruRU', 'Этот звук... Ты тоже его слышишь?', '', 64978),
(281141, 'ruRU', 'Герой, Аратор... Что привело вас на К\'ареш?', '', 64978),
(281138, 'ruRU', 'Я соберу бойцов и вернусь с ними на Азерот. Мы придем на помощь, Аратор.', '', 64978),
(281128, 'ruRU', 'Аллерия? В городе ее нет, это все, что могу сказать.', '', 64978),
(281127, 'ruRU', 'Мне неизвестно, где сейчас Аллерия. Но ее коллега Умбрий часто бывает на северной террасе.', '', 64978),
(281000, 'ruRU', 'Пожалуй, время рассудит. Но одно мы знаем точно: пусть и без того долгая, сага о Кель\'Таласе еще очень далека от своего завершения.', '', 64978),
(280999, 'ruRU', 'Но стоит ли здесь кого-то винить? Изучать то, что может принести вред, безрассудно. Но отвергать тех, кто это делает, тоже не всегда верно.', '', 64978),
(280998, 'ruRU', 'По иронии судьбы, их, как и предшественников, высших эльфов, отвергли за изучение запретной магии.', '', 64978),
(280997, 'ruRU', 'Тем временем эльфы Бездны, стремящиеся к тайным знаниям невзирая на страх и риск, были изгнаны из своего дома.', '', 64978),
(280996, 'ruRU', 'Эльфы Кель\'Таласа разделились. Эльфы крови хорошо помнили, к чему может привести погоня за силой, и защищали Солнечный Колодец.', '', 64978),
(280972, 'ruRU', '<Крышка бочки все еще не поддается.>', '', 64978),
(280968, 'ruRU', '<На боковой стороне бочки красуется вмятина: дерево вокруг металлического кольца проломилось и прогнулось. Крышка накрепко застряла.>', '', 64978),
(280910, 'ruRU', '', 'Но мы все исправили – ты бы видел! Этот день посвящен духу приключений, и я никому не дам это забыть!', 64978),
(280843, 'ruRU', 'Чэнь вернулся! Что он сварит теперь?', 'Чэнь вернулся! Что он сварит теперь?', 64978),
(280803, 'ruRU', 'В последнее время в фестивале духов участвует все меньше пандаренов.\n\nПотому я и пригласил вас. Если вы все поможете, быть может, нам удастся воодушевить остальных жителей острова.\n\nНо если это будет последний фестиваль, так тому и быть. Я не настолько закоснел, чтобы не понимать, что времена меняются и это нормально.\n\nЛи Ли старается не подавать виду, но для нее очень важен этот фестиваль. Это ради нее я стараюсь.', '', 64978),
(280767, 'ruRU', 'Смотрите! Тренировочная площадка Шан Си!', '', 64978),
(280758, 'ruRU', 'Устраивайся поудобней. Шар доставит нас на острова, но это будет небыстро.', '', 64978),
(280649, 'ruRU', 'Так! Еды и питья мне пока хватит, а слушать разные истории я всегда готов. Кто будет рассказывать дальше?', '', 64978),
(280636, 'ruRU', '<Этот воздушный шар может отвезти вас в деревню У-Сун на Скитающемся острове.>', '', 64978),
(280634, 'ruRU', '<Этот воздушный шар может отвезти вас в деревню У-Сун на Скитающемся острове.>', '', 64978),
(280628, 'ruRU', '<Этот воздушный шар может отвезти вас в Штормград.>', '', 64978),
(280575, 'ruRU', 'Восхитительно! Еще несколько испытаний, и наше изобретение можно запускать в серию.', '', 64978),
(280574, 'ruRU', 'Эти дюны кишат фазовыми паразитами. Опробуй на них экспериментальный метод ликвидации вредителей.', '', 64978),
(280476, 'ruRU', 'Да, конечно. Как я мог не пригласить нашего героя?', '', 64978),
(280390, 'ruRU', '<Хо танцует перед огнем, наслаждаясь его теплом. Он рад, что вы его нашли!>', '', 64978),
(280389, 'ruRU', '<Угоу фыркает от неожиданности и просыпается. Вы нашли его, но не дали ему подремать!>', '', 64978),
(280388, 'ruRU', '<Шу хихикает и брызгает в вас струйкой воды. Он рад, что вы его нашли!>', '', 64978);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(280349, 'ruRU', '<Дафэн танцует и кружится в небе над вами. Он очень рад, что вы его нашли!>', '', 64978),
(280231, 'ruRU', '', 'Хо! Ты в порядке!', 64978),
(279817, 'ruRU', 'Чтобы усилить подношение, убивайте элитных бойцов Н\'Зота в Штормграде.', 'Чтобы усилить подношение, убивайте элитных бойцов Н\'Зота в Штормграде.', 64978),
(279609, 'ruRU', '<Шу кружит по кругу, указывая на воду и вопросительно смотря на вас.>', '', 64978),
(279591, 'ruRU', 'Животные испытали потрясение, но серьезно не пострадали. Спасибо тебе за помощь.', '', 64978),
(279589, 'ruRU', 'Из заповедника убежало несколько животных. Они не выживут в пустошах! Скорее верни их!', '', 64978),
(279569, 'ruRU', '', 'Спасибо. Надеюсь, теперь она разберется со всем этим.', 64978),
(279568, 'ruRU', '', 'Главный почтальон – из твоего мира. Может, хоть ты поймешь, как она сортирует посылки?', 64978),
(279567, 'ruRU', '', 'Мало нам было других проблем... Так теперь еще и почта скопилась!', 64978),
(279544, 'ruRU', '', 'Сюда! Тут поток воздуха!', 64978),
(279543, 'ruRU', '', 'Я чувствую силу духа ветра. Он где-то рядом.', 64978),
(279542, 'ruRU', '', 'Эти сферы оставил Дафэн?', 64978),
(278998, 'ruRU', 'Это была случайность, но она дала Роммату повод выдворить эльфов Бездны и Умбрия из Луносвета... и вынудить Аллерию отправиться на поиски.', '', 64978),
(278995, 'ruRU', 'Первый эльф, подчинивший силу Бездны, был изгнан из Луносвета. Возможно, несправедливо. Ее имя – Аллерия Ветрокрылая.', '', 64978),
(278907, 'ruRU', 'Эльфы крови выбрали свое новое имя в честь павших собратьев, чтобы память о них никогда не угасла.', '', 64978),
(278846, 'ruRU', 'Да это же $p! Здравствуй!\n\nПоучаствуешь в фестивале духов? Я захватил целый мешок ингредиентов для новых напитков... Наш городок ждет настоящий праздник вкуса!\n\nУверен, братец Чунь уже наварил хмеля по своему старому рецепту. Устроим свой Хмельной фестиваль!', '', 64978),
(278845, 'ruRU', '', 'Ну что, отправляемся?\n\n<Ли Ли фыркает, скрестив руки на груди.>\n\nПандарены соберутся, чтобы есть, пить, танцевать и петь песни о великом предке Лю Лане... Вот только никто больше не чествует его наследие.\n\nСколько я себя помню, фестиваль служит для всех предлогом отдохнуть и повеселиться. В этом, конечно, нет ничего плохого... Но изначальная суть фестиваля духов не в этом.\n\n<Ли Ли выдавливает улыбку.>\n\nЛадно, это не важно. Зато отец будет рад меня повидать. Давай поучаствуем в фестивале и хорошо проведем время.', 64978),
(278844, 'ruRU', '', 'Как здорово, что ты здесь, $p! Значит, мое письмо нашло тебя. Ли Ли вплоть до твоего прибытия не могла решить, отправиться домой или нет.\n\nЯ ее понимаю. Возвращаться после стольких лет нелегко, особенно во время большого торжества, где соберутся старые друзья и знакомые.\n\nА вот мне просто не терпится встретиться с Цзи и отлично провести время. Он будет ждать нас на острове.', 64978),
(278840, 'ruRU', 'Конечно, Бел\'амет не заменит Дарнас, но здесь можно отдохнуть от горестей и обрести надежду. Как раз то, что нужно народу, который столько перенес.', '', 64978),
(278832, 'ruRU', 'Луносвету грозит беда?! Тогда мы все должны прийти ему на помощь. Рен\'дорай обязательно помогут, я уверен.\n\nЯ расскажу, где искать Аллерию. В общих чертах.', '', 64978),
(278818, 'ruRU', '', 'Тогда ей тем более придется держаться подальше. Ее связь с Бездной опасна для Солнечного Колодца.', 64978),
(278718, 'ruRU', '', 'Дело точно выгорит... если ты ничего не испортишь!', 64978),
(278646, 'ruRU', 'Наступает веселый праздничный сезон, $n!', '', 64978),
(278631, 'ruRU', 'Как листья разлетаются с дерева, если его встряхнуть, так же и эльфы разлетелись-разбрелись по всему Азероту. Каждый в свое время оторвался от ветки родимой, каждого унесли ветра перемен...', '', 64978),
(278494, 'ruRU', 'На ошибках прошлого можно многому научиться. Хочешь взглянуть на историю клана Черного Железа?', '', 64978),
(278348, 'ruRU', '', 'Только смотри не вляпайся в зеленую жижу. Она воняет хуже, чем оргриммарские улицы!', 64978),
(278336, 'ruRU', '', 'Вся моя команда потерялась где-то здесь. Можешь их найти?', 64978),
(278335, 'ruRU', '', 'Охо-хо-хо...', 64978),
(278090, 'ruRU', 'Прогноз погоды: облачно, возможны ВЗРЫВЫ!', '', 64978),
(278075, 'ruRU', 'Спасибо, Умбрий. С тобой и моей матерью Луносвету нечего бояться.', '', 64978),
(278058, 'ruRU', 'Скоро мы нанесем удар и навсегда избавимся от эльфов Бездны.', '', 64978),
(278057, 'ruRU', 'Увидишь их, сразу убей. Я отправляюсь в руины над Шан\'дорой.', '', 64978),
(278056, 'ruRU', 'Гляди в оба. Госпожа сообщила мне, что сын Аллерии прибыл на К\'ареш.', '', 64978),
(278043, 'ruRU', 'Давай спрячемся рядом, за теми бочками.', '', 64978),
(278042, 'ruRU', '', 'Вот он!', 64978),
(277995, 'ruRU', '', 'Когда вы с Аратором прошли через врата, за вами просочилась энергия Бездны. Опасно держать врата открытыми.\n\nТак что поскорее возвращайся туда и заверши начатое.', 64978),
(277975, 'ruRU', '', 'Эти врата работают в оба конца, но я не советую вам задерживаться в Утробе.', 64978),
(277973, 'ruRU', '', 'Иди вон туда и активируй врата.', 64978),
(277953, 'ruRU', '', 'Скажу, не тая. Это будет очень опасно, особенно для Аратора. С Утробой шутки плохи.\n\nВы точно к этому готовы?', 64978),
(277947, 'ruRU', '', 'Раньше они открывали проход между Темными Землями и миром живых. Пусть послужат и сейчас.', 64978),
(277919, 'ruRU', '', 'Врата в Утробу можно открыть... Хотя я не советую вам этого делать.', 64978),
(277918, 'ruRU', '', 'Ах вот, значит, как? Это мне за то, что я сама часто не слушалась мать.', 64978),
(277917, 'ruRU', '', 'Она была... строгой, но любящей. Хотела, чтобы я оставалась на защите границ Кель\'Таласа, как полагалось нашей семье.', 64978),
(277914, 'ruRU', 'И таким же бунтарем, как ты.', '', 64978),
(277913, 'ruRU', '', 'Клянусь, Аратор... Порой ты так же упрям, как твой отец.', 64978),
(277912, 'ruRU', '', 'Аратор... Я не могу тебя остановить. Но обещай, что не сгинешь в Утробе.', 64978),
(277905, 'ruRU', 'Еще совсем немного! Продолжай бороться...', '', 64978),
(277903, 'ruRU', 'Ты даже... не представляешь...', '', 64978),
(277873, 'ruRU', 'Давай... обратим... его силу... против него... самого!', '', 64978),
(277871, 'ruRU', '', 'Я... тебя... убью!', 64978),
(277870, 'ruRU', 'Твой сын скоро умрет, Аллерия. И тогда я займусь тобой.', '', 64978),
(277869, 'ruRU', '', 'Аратор! Нет!', 64978),
(277868, 'ruRU', 'Досадно... Посмотрим, как справится твое отродье.', '', 64978),
(277861, 'ruRU', 'Берегись!', '', 64978),
(277860, 'ruRU', 'Хватит вмешиваться, ничтожество из плоти.', '', 64978),
(277859, 'ruRU', '', 'Он сильнее, чем я думала. Помоги мне с ним совладать.', 64978),
(277800, 'ruRU', '', 'Где Ксал\'атат? Где ее армия?', 64978),
(277799, 'ruRU', 'Я... здесь хозяин. А ты... жалкий эльф!', '', 64978),
(277793, 'ruRU', 'Глупцы! Чего вы надеетесь добиться? Я не сдамся!', '', 64978),
(277791, 'ruRU', '', 'Герой, размести средоточия. Они подорвут силы Вешина.', 64978),
(277774, 'ruRU', '', '$n, для нас жизненно важно как можно больше узнать о планах Ксал\'атат.\n\nЯ найду ее. И остановлю.', 64978),
(277653, 'ruRU', 'Увидимся внизу.', '', 64978),
(277652, 'ruRU', 'Это еще не конец!', '', 64978),
(277640, 'ruRU', 'Прикрепи к нему метку и идем отсюда!', '', 64978),
(277639, 'ruRU', 'Я хотел спросить у тебя то же самое!', '', 64978),
(277638, 'ruRU', 'Хочешь сдаться, дитя?', '', 64978),
(277612, 'ruRU', 'Я готов выступать, сразу за тобой.\n\nКак только одолеем Вешина, прикрепи к нему метку переноса.', '', 64978),
(277596, 'ruRU', '', 'Чтобы метка сработала, Вешина нужно ослабить. Убивать не надо.', 64978),
(277595, 'ruRU', 'Не волнуйся. Я умею сдерживаться, когда это нужно.', '', 64978),
(277554, 'ruRU', '', 'Передавай привет Аллерии.', 64978),
(277552, 'ruRU', '', 'Не мешкай. Тебе нужна клетка, а мне... кое-что другое.', 64978),
(277536, 'ruRU', '', 'Кто это решил заглянуть в наш славный заповедник?', 64978),
(277534, 'ruRU', '', 'Приготовься. Ве\'нари что-нибудь потребует за эту клетку.', 64978),
(277533, 'ruRU', '', 'Мы с Аратором будем ждать тебя в Шан\'доре.', 64978),
(277414, 'ruRU', '', 'За мной.', 64978),
(277404, 'ruRU', '', 'Тише. Он идет.', 64978),
(277386, 'ruRU', 'Вериса считает, что она захочет защитить Луносвет.', '', 64978),
(277385, 'ruRU', '', 'Вериса... всегда видела в ней добро. Даже когда было ясно, каким чудовищем стала наша сестра.', 64978),
(277383, 'ruRU', '', 'Исключено! Не рискуй душой в Утробе, чтобы все равно получить отказ!', 64978),
(277382, 'ruRU', 'Если ты не поможешь, попрошу Сильвану.', '', 64978),
(277378, 'ruRU', '', 'Немногие способны изловить жертву и получить у нее нужные знания. Это могу только я.', 64978),
(277377, 'ruRU', '', 'Тем более я должна остаться. Теперь, когда Странник...', 64978),
(277375, 'ruRU', 'Что здесь такого важного, из-за чего ты не можешь вернуться на Азерот? Даже Умбрий отозвал рен\'дорай.', '', 64978),
(277271, 'ruRU', '', 'Маскировка не обманет здешних наблюдателей.', 64978),
(277236, 'ruRU', '', 'Так, ты иди вперед. Аратор, держись рядом.', 64978),
(277234, 'ruRU', '', 'Аратор... Меня изгнали из Луносвета. Одно мое присутствие может навредить Солнечному Колодцу.', 64978),
(277232, 'ruRU', 'Если Кель\'Талас в опасности, наш семейный долг – его защитить.', '', 64978),
(277231, 'ruRU', 'Да. Видение было не совсем ясное, но она узнала в нем некоторые здания Луносвета.', '', 64978),
(277230, 'ruRU', '', 'Это правда? Вериса видела нападение на Азерот?', 64978),
(277211, 'ruRU', '', 'Что такое? Почему ты здесь?', 64978),
(277210, 'ruRU', '', 'Рада видеть тебя, герой.\n\nТут... довольно одиноко. Но кто-то должен исполнять этот долг.', 64978),
(277158, 'ruRU', 'Приветствую, |3-6($r). Я торговец Ба\'крил из картеля Ба.\n\nЧем могу помочь?', '', 64978),
(277138, 'ruRU', '', 'Вот теперь! ...Аратор? Что ты тут делаешь?', 64978),
(277124, 'ruRU', 'Мама?', '', 64978),
(277122, 'ruRU', 'То, что случилось с этим миром, просто ужасно. Я был в Запределье и на Аргусе, но это еще хуже.', '', 64978),
(277120, 'ruRU', 'Я знаю, кого можно спросить. Кто-то из них должен знать, где найти Аллерию.', '', 64978),
(277028, 'ruRU', '', 'Я должна была знать, что этот бардак – твоих рук дело. Что-что, а провоцировать конфликты ты отлично умеешь.', 64978),
(277018, 'ruRU', 'Это место... Здесь будто сам воздух сжимает сердце мертвой хваткой.\n\nДавай сделаем то, за чем мы пришли, и уйдем отсюда.', '', 64978),
(276983, 'ruRU', 'Аратор молча наблюдает за тем, как Сильвана достает свою неземную лиру.', '', 64978),
(276934, 'ruRU', 'Это место, этот мир... Он будто пропитался силой Бездны.', '', 64978),
(276908, 'ruRU', 'Мне надо... перевести дух.', '', 64978),
(276898, 'ruRU', 'Это мы еще посмотрим.', '', 64978),
(276897, 'ruRU', 'Попробуй, да только вряд ли получится!', '', 64978),
(276889, 'ruRU', 'Но их конечная цель не имеет значения. Сумеречный Клинок надо остановить.', '', 64978),
(276888, 'ruRU', 'По названию сразу ясно, что эти фанатики служат Ксал\'атат.', '', 64978),
(276887, 'ruRU', 'Этот культ похож на Сумеречный Молот. Те же сектанты, только судный день у них другой.', '', 64978),
(276886, 'ruRU', 'Сумеречный Клинок... Видимо, это и есть угроза из видения.', '', 64978),
(276883, 'ruRU', 'А... что насчет Сильваны?', '', 64978),
(276882, 'ruRU', 'Надо рассказать моей матери. Она боролась с Ксал\'атат дольше всех.', '', 64978),
(276881, 'ruRU', '', 'Мои видения до сих пор трудно разобрать. Но они явно предупреждают нас: Ксал\'атат готовит наступление на Азерот.', 64978),
(276880, 'ruRU', '', 'Именно поэтому она не может вернуться. Аллерия готова преследовать свою цель хоть до края вселенной.', 64978),
(276879, 'ruRU', 'А если на Луносвет все же нападут?', '', 64978),
(276605, 'ruRU', '', 'Пора.\n\n<Сильвана окидывает вас взглядом.>\n\nНе стоит так нервничать. Я уже много раз это проделывала.', 64978),
(276598, 'ruRU', 'Бездна... поглотит... этот мир...', '', 64978),
(276597, 'ruRU', 'Если эти Сумеречные глупцы не справятся, я сам вас убью.', '', 64978),
(276565, 'ruRU', '', 'Сияющая Песнь... прекрасна, но... Это слишком.', 64978),
(276564, 'ruRU', '', 'Обо мне не волнуйся. Сейчас я приду в себя...\n\nПомоги пока Аратору. Это все слишком... личное.', 64978),
(276560, 'ruRU', '', 'Это видение... Я не могу...', 64978),
(276557, 'ruRU', 'Верные слуги Сумеречного Клинка! Убейте Ветрокрылых!', '', 64978),
(276517, 'ruRU', '', 'Да, здесь лучше всего.', 64978),
(276513, 'ruRU', '', 'Даже так близко к Артерии я не могу вызвать видения, когда захочу.', 64978),
(276502, 'ruRU', '', 'Благодарю тебя, $n. Я очень скучаю по мужу.', 64978),
(276438, 'ruRU', '', 'Хорошо, что ты здесь. Мне начали являться обрывки Сияющей Песни. Эти... видения приходят и уходят, но они смутные и неясные. Все разрушается, повсюду крики и смерть.\n\nС тех пор как мы сюда прибыли, видения усилились и приносят больше боли. Но я справлюсь.\n\nНам надо многое обсудить, а времени совсем мало.', 64978),
(276409, 'ruRU', 'Мы надеемся, близость к Артерии усилит и прояснит их. Давай встретимся на острове Дорн.', '', 64978),
(276407, 'ruRU', 'Послушай... Мою тетю Верису посещают видения Сияющей Песни. Они мрачные, но неясные.', '', 64978),
(276403, 'ruRU', 'Я рад, что ты здесь, герой. Твои навыки славятся по всему Азероту и за его пределами.\n\nНадеюсь, ты сумеешь нам помочь.', '', 64978),
(276402, 'ruRU', '', 'Даларан... Я должна была прийти раньше.', 64978),
(275431, 'ruRU', '', 'К чему спешить? Расслабьтесь!', 64978),
(275418, 'ruRU', 'Мы еще не закончили! Я докажу, что я ГЕНИЙ!', '', 64978),
(273984, 'ruRU', '', 'И множество новых знакомств! Наслаждайся.', 64978),
(273983, 'ruRU', 'Очень мудрая мысль. Что ж... Пожалуй, меня ждет много новых историй.', '', 64978),
(273982, 'ruRU', '', 'Получается, чтобы оценить что-то по достоинству, нужно увидеть это глазами другого.', 64978),
(273981, 'ruRU', '', 'Я чувствовала то же самое, когда впервые ступила на берега Пандарии.', 64978),
(273980, 'ruRU', '', 'Ха! Раньше я считала все это скукой смертной! Но... я понимаю, о чем ты.', 64978),
(273979, 'ruRU', 'Это место, этот фестиваль... Надеюсь, ты понимаешь, как это волшебно, Ли Ли.', '', 64978),
(273978, 'ruRU', 'Да! Я слышал о путешествии Шэнь-Цзынь Су только в сказках. И вот я увидел, как он возвращается в Пандарию... В голове не укладывается.', '', 64978),
(273977, 'ruRU', '', 'Или в легенду?', 64978),
(273976, 'ruRU', 'Я как будто попал в сон.', '', 64978),
(273975, 'ruRU', 'Мы дополняем друг друга. Я ценю это так же сильно, как ценю тебя.', '', 64978),
(273974, 'ruRU', '', 'Хвала духам! Ты помогаешь мне сохранять равновесие, Цзи.', 64978),
(273973, 'ruRU', 'К счастью, мы все уладили и всех успокоили... всех без исключения.', '', 64978),
(273972, 'ruRU', '', 'И мне ужасно стыдно, что я так легко обвинила хозенов. Доказательства обратного были прямо передо мной.', 64978),
(273971, 'ruRU', '', 'Приятно видеть, что между Ки Ки и Цзя возникла такая дружба.', 64978),
(273970, 'ruRU', 'И тебя даже не смущают гости-хозены?', '', 64978),
(273969, 'ruRU', '', 'Как здорово, что мы помогли острову вновь полюбить фестиваль.', 64978),
(273968, 'ruRU', '', 'Привет, Бо. Жаль, ты не сможешь заглянуть на фестиваль. Кстати, он чуть не сорвался.', 64978),
(273967, 'ruRU', '', 'Прости, что давно не приходила, Бо. Мир за стенами дома такой огромный...', 64978),
(273966, 'ruRU', '', 'Я... тоже тебя люблю.', 64978),
(273965, 'ruRU', '', 'Мы можем вспоминать ее вместе.', 64978),
(273948, 'ruRU', '', 'Я рада, что ты сейчас со мной. Идем.', 64978),
(273945, 'ruRU', '', 'Спасибо, Угоу! Скорее, дружок!', 64978),
(273933, 'ruRU', 'Со вкусом дома ничто не сравнится.', '', 64978),
(273932, 'ruRU', 'Твой рецепт древний, как сам Лю Лан. Попробовал бы что-нибудь новое!', '', 64978),
(273930, 'ruRU', 'Поразишь – это точно. А насчет \"восхитишь\" не уверен.', '', 64978),
(273928, 'ruRU', 'Я удивлю и восхищу тебя вкусами и рецептами со всего мира, братец!', '', 64978),
(273706, 'ruRU', '', 'Интересно, а духи знали, что происходило с Шэнь-Цзынь Су? Поэтому они были в таком смятении? Или... мы как-то повлияли на все, что произошло?\n\n<Ли Ли задумчиво пережевывает пельмень.>\n\nЗнаешь, $p, а ведь еще чуть-чуть – и я бы пропустила нашу встречу у воздушного шара. <Ли Ли складывает палочки так, чтобы между ними образовалась тонкая щелочка, и демонстративно указывает на нее.> Мне казалось, что фестиваль утратил всю свою значимость. Когда мы сюда добрались, всеобщее равнодушие меня совсем не удивило. Но раз уж я не могла просто улететь обратно, то решила помочь.\n\nЗдорово было повидать отца с братом. А еще маму и Бо. Да и всех остальных.\n\n<Ли Ли отправляет в рот еще один пельмень.>\n\nОбязательно их попробуй! Клянусь лапами, мне нужна еще тарелка.', 64978),
(273705, 'ruRU', 'Как насчет дружеского боя?', 'Как насчет дружеского боя?', 64978),
(273693, 'ruRU', 'С возвращением, $p. С тобой в наш дом снова пришло тепло.', '', 64978),
(273691, 'ruRU', '', 'Раньше мы с Цзи устраивали тренировочные бои на этом мосту.\n\nПроигравший отправлялся в воду!', 64978),
(273690, 'ruRU', 'Помню, как я учился плавать в этой речушке.\n\n<Цзи с хитринкой посмотрел на Аису.>\n\nОна отличный учитель.', '', 64978),
(273689, 'ruRU', 'Крохи-шнуропсы смотрят, как черепаха носится!\n\nТеперь у нас много бананов. От тебя. Мы рады, очень рады.\n\n<Вождь замолкает, подбирая подходящее слово.>\n\nТы это... Спасибо.', '', 64978),
(273688, 'ruRU', 'Только посмотри, какая очередь! Почти все пробуют напитки Чэня и возвращаются за добавкой!\n\nПохоже, придется помочь ему приготовить новую партию. Что ж, учиться чему-нибудь новому даже полезно... время от времени.\n\n<Чунь шмыгает носом, пытаясь скрыть свой азарт.>\n\nЗнаешь, я бы выпил еще один манговый мартини.', '', 64978),
(273687, 'ruRU', 'Чунь По сказал мне, что если бы не любовь к приключениям, которую разделяем мы с Ли Ли, такой день, как сегодня, просто бы не наступил. Я спросил, почему он так считает.\n\nОн ответил: \"Как тосковать по дому, ни разу его не покинув? Как радоваться возвращению дорогих друзей и родных, если они всегда рядом?\"\n\nЗабавно... Мой брат повидал куда меньше моего, но вот какой мудрый.', '', 64978),
(273686, 'ruRU', 'Это ведь Шу? Там, позади нас? Как он радуется!\n\nЯ почти каждый день хожу посидеть на краю черепахи. Сколько я себя помню, передо мной всегда открывался пустой горизонт – лишь широкий простор океана.\n\nЗакрой глаза и вдохни поглубже. Замечаешь что-нибудь?\n\n<Старик Лян делает вдох и выдох.>\n\nБолее теплая и свежая вода. Кисловатый запах травы на новой земле. Клич прибрежных птиц вдалеке.\n\n<Старик Лян улыбается.>\n\nЗначит, Пандария... Похоже, этому старику еще найдется, ради чего пожить.', '', 64978),
(273684, 'ruRU', 'Малыши канючат, чтобы я разбил бочку, но я еще не поел!', '', 64978),
(273679, 'ruRU', 'Когда Ли Ли пригласила меня на фестиваль, я с горечью приготовился отказаться. Меня ждали приключения, которые нельзя было откладывать. К тому же фестиваль проводят каждый год – пропущу этот, попаду на другой. Какая разница, в этом году я приду или в следующем?\n\nКак я ошибался... Хотя Юй-лун огромна, я услышал ее прежде, чем она показалась мне на глаза. Она была в гневе на меня, но и в радостном предвкушении. Она потребовала, чтобы я немедленно сопроводил ее.\n\n<Хранитель истории Чо жестом указывает на Юй-лун, парящую наверху.>\n\nЕй стало известно, что Шэнь-Цзынь Су прибыл в Пандарию. Конечно, она узнала бы такую новость одна из первых.\n\nТебе и Буйным Портерам удалось исцелить что-то глубоко в душе Шэнь-Цзынь Су. И я подозреваю, что с этой истории все только начинается.', '', 64978),
(273514, 'ruRU', 'В какую даль ни занесут тебя ветра, я всегда буду дома, ждать новой встречи.', '', 64978),
(273513, 'ruRU', 'Вы с ней очень похожи. Вы свободные, своевольные, подчас можете вывести из себя, но я люблю вас обеих.', '', 64978),
(273511, 'ruRU', 'Вот почему... хоть это и плохое оправдание, мне так не хотелось тебя отпускать.', '', 64978),
(273509, 'ruRU', 'У тебя ее глаза. А порой, стоит тебе засмеяться, мне кажется, что она снова с нами.', '', 64978),
(273508, 'ruRU', 'Хочешь увидеть маму, просто посмотри в зеркало, моя жемчужинка.', '', 64978),
(273507, 'ruRU', '', 'Я не помню ни ее лица, ни голоса. Ведь я была совсем маленькой, когда ее не стало.', 64978),
(273506, 'ruRU', 'О маме?', '', 64978),
(273505, 'ruRU', '', 'Папа... а можешь о ней рассказать?', 64978),
(273502, 'ruRU', '', 'Отец... Мне казалось, что он никогда не изменится. Он всегда был постоянным и непреклонным, как скала.\n\n<Ли Ли внезапно замолкает.>\n\nОн будто постарел, тебе не кажется? И немного осунулся.', 64978),
(273441, 'ruRU', '', 'Фух! А теперь вперед, все четверо! Сейчас же фестиваль духов! Встретимся там.', 64978),
(273422, 'ruRU', 'Я и не сомневался. А как ты? По-моему, они не впечатлились.', '', 64978),
(273410, 'ruRU', 'Раз Ки Ки и шнуропсик просят, то как нет?', '', 64978),
(273409, 'ruRU', '', 'Пожалуйста!', 64978),
(273408, 'ruRU', 'Можно? Дава-а-ай!', '', 64978),
(273407, 'ruRU', '', 'И вы все приходите. Простите за обвинения.', 64978),
(273406, 'ruRU', 'Эй, детишки, отнесите фейерверки на фестиваль!', '', 64978),
(272889, 'ruRU', 'Хорош! Сюда, вонючка! Смотри, что покажу!', '', 64978),
(272888, 'ruRU', 'Да не крали мы! Вонючка-шнуропсина!', '', 64978),
(272887, 'ruRU', '', 'Здесь наверняка были хозены – можно не сомневаться!', 64978),
(272886, 'ruRU', 'Но хозены едят бананы, а не собирают их кучами.', '', 64978),
(272885, 'ruRU', '', 'У них разная шерсть, Цзи. Это явная улика.', 64978),
(272884, 'ruRU', 'Хм... У хозенов шерсть не такая мягкая.', '', 64978),
(272883, 'ruRU', 'Шум был такой, будто здесь бегали два хозена и все громили!', '', 64978),
(272882, 'ruRU', '', 'Постойте... Почему там так пусто и тихо?', 64978),
(272881, 'ruRU', 'И храм Пяти Рассветов.', '', 64978),
(272880, 'ruRU', '', 'А вот и она! Деревня У-Сун, место проведения фестиваля!', 64978),
(272879, 'ruRU', '', 'Смотрите! Тренировочная площадка Шан Си!', 64978),
(272877, 'ruRU', 'Может, через год, когда он будет не так занят.', '', 64978),
(272876, 'ruRU', '', 'Жаль, хранитель истории Чо не с нами.', 64978),
(272567, 'ruRU', '', 'Лети с ним, а я отправлюсь следом.', 64978),
(272566, 'ruRU', '', 'А вот и он! Но куда он тебя уводит?', 64978),
(272565, 'ruRU', '', 'Ух ты! Поищи Дафэна в небе!', 64978),
(272564, 'ruRU', 'Обо мне еще заговорят. Вот увидишь на фестивале.', '', 64978),
(272563, 'ruRU', 'Неплохо, Чунь По. Есть еще порох в пороховницах!', '', 64978),
(272562, 'ruRU', 'Мой хмель всем вскружит голову!', '', 64978),
(272561, 'ruRU', 'Ха! Какие мы самоуверенные.', '', 64978),
(272480, 'ruRU', 'Бочка с фейерверками, которые так и ждут, чтобы их подожгли.', '', 64978),
(272479, 'ruRU', '', 'Все собрались! Зажигай фейерверки!', 64978),
(272475, 'ruRU', '', 'Я тоже.', 64978),
(272474, 'ruRU', 'Я решил зайти сюда перед фестивалем.', '', 64978),
(272473, 'ruRU', '', 'Папа! Я...', 64978),
(272472, 'ruRU', 'Ли Ли?', '', 64978),
(272403, 'ruRU', '<Огонь Хо радостно потрескивает. Он горит ярко и полон сил!>', '', 64978),
(272379, 'ruRU', '<Дафэн явно обеспокоен. Его друг совсем выбился из сил!>', '', 64978),
(272337, 'ruRU', '<Дух земли укрепил вашу кожу, и теперь вы можете прикоснуться к Хо, не боясь обжечься.\n\nНо Хо вот-вот исчезнет без какого-нибудь топлива.>', '', 64978),
(272329, 'ruRU', '<Угоу выпрямляется во весь рост. Он готов помочь!>', '', 64978),
(272314, 'ruRU', '', 'Этот жар... Хо наверняка там, наверху! Но как бы нам не обжечься... Что если... Угоу?', 64978),
(272153, 'ruRU', 'Стромгард превыше всего.', 'Стромгард превыше всего.', 64978),
(272120, 'ruRU', '', 'Мы с Угоу обойдем всю территорию.', 64978),
(272119, 'ruRU', '', 'Пусть Шу направляет тебя в пути.', 64978),
(272087, 'ruRU', 'Я поищу в другом месте. Увидимся, Ли Ли!', '', 64978),
(272001, 'ruRU', 'Они свободны! Скорее... они отправились к пруду.', '', 64978),
(272000, 'ruRU', 'Осталось найти Хо. Он наверняка рядом.', '', 64978),
(271998, 'ruRU', '', 'Ты иди с Йо-Йо. Я пойду за Дафэном.', 64978),
(271997, 'ruRU', 'Ли Ли! Духам нужна помощь!', '', 64978),
(271996, 'ruRU', '', 'Йо-Йо?', 64978),
(271960, 'ruRU', 'Ки Ки и шнуропсик играть! Прости-прости!', '', 64978),
(271959, 'ruRU', '', 'Простите! Я просто играла с Ки Ки!', 64978),
(271958, 'ruRU', 'Ну? Видишь, не крали мы. Их крохе-шнуропсу захотелось!', '', 64978),
(271948, 'ruRU', '', 'За ним!', 64978),
(271913, 'ruRU', '', 'Верните фейерверки!', 64978),
(271908, 'ruRU', 'Я злорадствовать не буду!', '', 64978),
(271907, 'ruRU', '', 'Если окажется, что ты прав...', 64978),
(271655, 'ruRU', '', 'Должно быть, воровали фейерверки.', 64978),
(271653, 'ruRU', 'Ну где же фейерверки для фестиваля? Не могу их найти! Они пропали!', '', 64978),
(271608, 'ruRU', '', 'Я тоже попробую кое-что разузнать. Увидимся!', 64978),
(271601, 'ruRU', '', 'Сначала надо разобраться, а уже потом делать выводы.', 64978),
(271600, 'ruRU', 'Мы заглянем в деревню Утреннего Бриза. Небось хозены что-то затеяли.', '', 64978),
(271474, 'ruRU', 'Чем это пахнет? Манго?', '', 64978),
(271469, 'ruRU', 'И не только. Скоро увидишь!', '', 64978),
(271424, 'ruRU', 'А вот тут понадобится ваша помощь.', '', 64978),
(271423, 'ruRU', '', 'Папа... Куда все пропали?', 64978),
(271422, 'ruRU', 'Чэнь! Ли Ли! С возвращением.', '', 64978),
(271421, 'ruRU', 'Чунь По! А вот и мы!', '', 64978),
(271386, 'ruRU', '', 'Да, конечно. Скоро наш герой будет здесь!', 64978),
(271234, 'ruRU', 'Я ничего не видел, зато кое-что слышал!', '', 64978),
(271232, 'ruRU', 'Хозены больше не приближаются к нашей деревне. Они не забыли твой урок!', '', 64978),
(271227, 'ruRU', 'Остренько! А потом... карамельно?', 'Остренько! А потом... карамельно?', 64978),
(271226, 'ruRU', 'На вкус немного... странновато.', 'На вкус немного... странновато.', 64978),
(271225, 'ruRU', 'Обычно манго не такое кислое...', 'Обычно манго не такое кислое...', 64978),
(271224, 'ruRU', 'Вот это то, что надо!', 'Вот это то, что надо!', 64978),
(271223, 'ruRU', 'Домашний хмель самый лучший.', 'Домашний хмель самый лучший.', 64978),
(271222, 'ruRU', 'Хорошо пошло!', 'Хорошо пошло!', 64978),
(271219, 'ruRU', 'И как нам все это переправить?', 'И как нам все это переправить?', 64978);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(271218, 'ruRU', 'Нет, мои фрукты! Они же для фестиваля!', 'Нет, мои фрукты! Они же для фестиваля!', 64978),
(271217, 'ruRU', 'Сюда!', 'Сюда!', 64978),
(271216, 'ruRU', 'Не трогайте мой урожай!', 'Не трогайте мой урожай!', 64978),
(271215, 'ruRU', 'На помощь! Нас окружили!', 'На помощь! Нас окружили!', 64978),
(271202, 'ruRU', 'Только не капусту!', 'Только не капусту!', 64978),
(271105, 'ruRU', '', 'Мы на месте!', 64978),
(266544, 'ruRU', 'Какое облегчение. Не дай кобольдам сбежать со всеми нашими инструментами.', 'Какое облегчение. Не дай кобольдам сбежать со всеми нашими инструментами.', 64978),
(266543, 'ruRU', 'Опробуй ботинки вон у того нерабочего очистителя. От сотрясения шестерни встанут на место.', 'Опробуй ботинки вон у того нерабочего очистителя. От сотрясения шестерни встанут на место.', 64978),
(266368, 'ruRU', 'Я посетил немало спектаклей Кукловода, прежде чем его постиг крах. Нерубы появились среди кукол совсем недавно. Сперва меня это шокировало, но, должен признать, такое смелое решение нельзя не уважать.\n\nК несчастью, не все разделяют мои взгляды. Помню, как зрители уходили посреди спектакля. Жалкие неженки.\n\nНекоторые считают, что именно этот шаг и погубил Кукловода. Говорят, он принялся совершать все более и более эксцентричные выходки – только для того, чтобы его не забывали, чтобы о нем говорили. Пытался подлизываться к магистрату...\n\nИ даже к тварям с поверхности, как оказалось.', 'Я посетила немало спектаклей Кукловода, прежде чем его постиг крах. Нерубы появились среди кукол совсем недавно. Сперва меня это шокировало, но, должна признать, такое смелое решение нельзя не уважать.\n\nК несчастью, не все разделяют мои взгляды. Помню, как зрители уходили посреди спектакля. Жалкие неженки.\n\nНекоторые считают, что именно этот шаг и погубил Кукловода. Говорят, он принялся совершать все более и более эксцентричные выходки – только для того, чтобы его не забывали, чтобы о нем говорили. Пытался подлизываться к магистрату...\n\nИ даже к тварям с поверхности, как оказалось.', 64978),
(266361, 'ruRU', 'Как тебе удалось сюда попасть?\n\nЕсли по приглашению... Я... слышал, что это место утратило свой элитный статус после того ужасного случая с существом с поверхности... Но все равно! Это определенно какая-то ошибка.', 'Как тебе удалось сюда попасть?\n\nЕсли по приглашению... Я... слышала, что это место утратило свой элитный статус после того ужасного случая с существом с поверхности... Но все равно! Это определенно какая-то ошибка.', 64978),
(266356, 'ruRU', 'Имя Кукловода втоптали в грязь, но никто другой не способен создавать такие потрясающие творения. Так управлять низшими существами может только истинный мастер, умелый и сильный.\n\nЕго спектакли – это не просто какое-то пустое развлечение. Они демонстрируют дар вознесенных. Именно мы держим нити, а остальные... лишь марионетки в наших руках.\n\nО, не расстраивайся, если твой примитивный разум не может постичь всю глубину нашего гения. Я и не жду особой утонченности от существа с поверхности.', 'Имя Кукловода втоптали в грязь, но никто другой не способен создавать такие потрясающие творения. Так управлять низшими существами может только истинный мастер, умелый и сильный.\n\nЕго спектакли – это не просто какое-то пустое развлечение. Они демонстрируют дар вознесенных. Именно мы держим нити, а остальные... лишь марионетки в наших руках.\n\nО, не расстраивайся, если твой примитивный разум не может постичь всю глубину нашего гения. Я и не жду особой утонченности от существа с поверхности.', 64978),
(266355, 'ruRU', 'Кукловод достает для своих кукол таких необычных существ...\n\nЕго творения... кошмарны, но есть в них какая-то мрачная красота. И какая прекрасная в них заложена идея... Мы, вознесенные, должны принять великую силу, которую даровала наша королева.\n\nДаже узнав, что он проиграл существу с поверхности, я вижу очень много хорошего в его творчестве.', 'Кукловод достает для своих кукол таких необычных существ...\n\nЕго творения... кошмарны, но есть в них какая-то мрачная красота. И какая прекрасная в них заложена идея... Мы, вознесенные, должны принять великую силу, которую даровала наша королева.\n\nДаже узнав, что он проиграл существу с поверхности, я вижу очень много хорошего в его творчестве.', 64978),
(266351, 'ruRU', 'Да, многие презирают Кукловода после того, как его одолело существо с поверхности, но... Скажу по секрету, некоторым из нас до сих пор нравится его творчество.\n\nЕсли кому-то расскажешь, я найду тебя и уничтожу.', 'Да, многие презирают Кукловода после того, как его одолело существо с поверхности, но... Скажу по секрету, некоторым из нас до сих пор нравится его творчество.\n\nЕсли кому-то расскажешь, я найду тебя и уничтожу.', 64978),
(265641, 'ruRU', 'Бежим отсюда скорее!', '', 64978),
(265640, 'ruRU', 'И мерзкий!', '', 64978),
(265639, 'ruRU', 'И гадкий!', '', 64978),
(265638, 'ruRU', 'Знаете, а он мне не очень-то и нравился. Слишком уж злой был!', '', 64978),
(265637, 'ruRU', 'Гринч побежден! Что нам теперь делать?', '', 64978),
(264736, 'ruRU', 'Зев\'калл назначил стражниками одних льстецов и подхалимов королевы. Будет просто ужасно, если кто-то решит очистить их ряды от недостойных.', 'Зев\'калл назначил стражниками одних льстецов и подхалимов королевы. Будет просто ужасно, если кто-то решит очистить их ряды от недостойных.', 64978),
(262705, 'ruRU', 'Арати падут, а за ними – все остальные.', '', 64978),
(262408, 'ruRU', 'Всё, тебе хватит!', '', 64978),
(261156, 'ruRU', '', 'Стена у них неплохая. Конечно, ее строили явно не земельники, но свою задачу она выполняет.\n\nЖалко, что ее пробили.\n\nМы со странниками бурь постараемся защитить эту башню, чтобы было где обороняться от нерубов.', 64978),
(261099, 'ruRU', 'Посмотри. Этот неруб похож на командира. Убьем его – остальные разбегутся.', '', 64978),
(258081, 'ruRU', 'Мы сделаем все, чтобы помочь Магни исцелиться от ран.', '', 64978),
(255893, 'ruRU', 'Беледар и так сияет как солнце. Неужели с башней станет еще светлее?', '', 64978),
(255313, 'ruRU', '', 'Нам было известно, что нерубы давным-давно воевали с арати. Мы, Освобожденные, могли бы им помочь.', 64978),
(255312, 'ruRU', 'Как хорошо ты знаешь этих арати? Думаешь, они помогут нам в борьбе с Ксал\'атат?', '', 64978),
(255242, 'ruRU', 'Теперь этот участок принадлежит вам!', '', 64978),
(255241, 'ruRU', 'Кажется, этот пустой участок отлично подойдет для строительства дома.', '', 64978),
(236167, 'ruRU', '', 'Потрясающе, $n! Каких высот тебе удалось достичь за короткое время! Надеюсь, на твоем пути к величию... обошлось без рискованных связей.\n\n<Релка ухмыляется. Ее мертвый глаз поблескивает из-под капюшона.>\n\nЯ думаю, мы можем многому друг у друга научиться. Надеюсь, мы еще встретимся после Кош\'харга.', 64978),
(208732, 'ruRU', '', 'Вот и конец нашим музыкантам. Что ж, хотя бы позабавились.', 64978),
(208694, 'ruRU', '', 'Тяжело угодить публике, не научившись играть.', 64978);
INSERT INTO `item_sparse_locale` (`ID`, `locale`, `Description_lang`, `Display3_lang`, `Display2_lang`, `Display1_lang`, `Display_lang`, `VerifiedBuild`) VALUES
(224752, 'ruRU', 'Текст на странице почти невозможно разобрать, однако она еще может пригодиться кому-нибудь из вашего отряда.', '', '', '', 'Промокшая страница из дневника', 64978),
(242709, 'ruRU', '', '', '', '', 'Character Bank Tab Bag (DNT)', 64978),
(208392, 'ruRU', '', '', '', '', 'Account Bank Tab Bag (DNT)', 64978);
